(function(){var d={"Direito Administrativo::Aula 12":{"questoesPdf":[{"title":"Questões Extraídas — LGPD (Lei 13.709/2018) · Aula 12 (22 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Direito Administrativo Aula 12 — Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">DIREITO ADMINISTRATIVO · AULA 12 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Direito Administrativo · Aula 12 — <b>Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Direito Administrativo · Aula 12 — questões extraídas do PDF (Prof. Herbert Almeida · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TCE MS · 2025\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Assinale a opção em que é citada sanção administrativa prevista na Lei Geral de Proteção de\\nDados Pessoais.\",\"c\":\"Examinando as sanções previstas no art. 52 da LGPD, percebemos que a letra (A) está correta:\\n\\n\\\"Art. 52. Os agentes de tratamento de dados, em razão das infrações cometidas às normas previstas nesta Lei, ficam sujeitos às seguintes sanções administrativas aplicáveis pela autoridade nacional: I - advertência, com indicação de prazo para adoção de medidas corretivas;\\\"\\n\\nAs letras (B) e (D) estão incorretas, pois a LGPD não prevê cassação do CNPJ como sanção, muito menos a prisão (apenas sanções administrativas, não sanções penais).\\n\\nA letra (C) está incorreta em razão do prazo. A suspensão do exercício da atividade de tratamento de dados tem período máximo de 6 (seis) meses, prorrogável por igual período, e não 3 meses.\\n\\n\\\"Art. 52, XI - suspensão do exercício da atividade de tratamento dos dados pessoais a que se refere a infração pelo período máximo de 6 (seis) meses, prorrogável por igual período;\\\"\\n\\nA letra (E) está incorreta, pois o limite da multa é de até 2% do faturamento, e não 1%.\\n\\n\\\"Art. 52. (..) II - multa simples, de até 2% (dois por cento) do faturamento da pessoa jurídica de direito privado, grupo ou conglomerado no Brasil no seu último exercício, excluídos os tributos, limitada, no total, a R$ 50.000.000,00 (cinquenta milhões de reais) por infração;\\\"\",\"o\":[\"advertência, com indicação de prazo para a adoção de medidas corretivas\",\"cassação definitiva do CNPJ da empresa infratora\",\"suspensão do exercício da atividade de tratamento dos dados pessoais a que se refere a\\ninfração pelo período máximo de 3 meses, prorrogável por igual período\",\"prisão do controlador de dados em caso de reincidência grave\",\"multa simples, de até 1% do faturamento da pessoa jurídica de direito privado, grupo ou\\nconglomerado no Brasil no seu último exercício, excluídos os tributos, limitada, no total, a R$\\n50.000.000\"],\"g\":0},{\"_id\":1,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TRF 6 Analista · 2025\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O tratamento de dados pessoais só poderá ser realizado nas hipóteses taxativas previstas na\\nLGPD, que incluem, por exemplo, a situação em que tal tratamento de dados visa ao exercício\\nregular de direitos em processo judicial, administrativo ou arbitral.\",\"c\":\"O item prevê corretamente uma das hipóteses de tratamento de dados:\\n\\nLei 13.709/2018, Art. 7º - O tratamento de dados pessoais somente poderá ser realizado nas seguintes hipóteses: (..)\\n\\nVI - Para o exercício regular de direitos em processo judicial, administrativo ou arbitral, esse último nos termos da Lei nº 9.307, de 23 de setembro de 1996 (Lei de Arbitragem).\",\"g\":\"C\"},{\"_id\":2,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TRF 6 Analista · 2025\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Para fins da LGPD, os dados anonimizados são considerados, em regra, dados pessoais.\",\"c\":\"O item está incorreto. Em regra, os dados anonimizados não serão considerados dados pessoais, conforme prevê o Art. 12 da Lei 13.709/2018:\\n\\nLei 13.709/2018, Art. 12 - Os dados anonimizados não serão considerados dados pessoais para os fins desta Lei, salvo quando o processo de anonimização ao qual foram submetidos for revertido, utilizando exclusivamente meios próprios, ou quando, com esforços razoáveis, puder ser revertido.\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TRF 6 Analista · 2025\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A Lei Geral de Proteção de Dados Pessoais (LGPD) não se aplica ao tratamento de dados\\npessoais realizado para fins exclusivos de atividades de investigação e repressão de infrações\\npenais.\",\"c\":\"O item está correto, ao mencionar hipótese de não aplicação da LGPD prevista em seu Art. 4º, inciso III:\\n\\nLei 13.709/2018, Art. 4º - Esta Lei não se aplica ao tratamento de dados pessoais:\\n\\n(..)\\n\\nIII - realizado para fins exclusivos de: (..)\\n\\nd) atividades de investigação e repressão de infrações penais;\",\"g\":\"C\"},{\"_id\":4,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"CGE RJ · 2024\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A LGPD não se aplica ao tratamento de dados pessoais realizado para fins exclusivos de\\natividades de investigação e repressão de infrações penais.\",\"c\":\"Questão correta, por disposição literal da LGPD, a lei não se aplica ao tratamento realizado para fins exclusivos de atividades de investigação e repressão de infrações penais, conforme art. 4º da Lei nº 13.709/2018:\\n\\nArt. 4º Esta Lei não se aplica ao tratamento de dados pessoais:\\n\\nIII - realizado para fins exclusivos de:\\n\\na) segurança pública;\\n\\nb) defesa nacional;\\n\\nc) segurança do Estado; ou\\n\\nd) atividades de investigação e repressão de infrações penais;\",\"o\":[],\"g\":2},{\"_id\":5,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"CGE RJ · 2024\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A LGPD aplica-se ao tratamento de dados pessoais coletados em território nacional.\",\"c\":\"Questão correta, uma das exigências possíveis para aplicação da LGPD é que os dados pessoais que sejam objeto de tratamento sejam coletados em território nacional, conforme disposições da Lei nº 13.709/2018:\\n\\nArt. 3º Esta Lei aplica-se a qualquer operação de tratamento realizada por pessoa natural ou por pessoa jurídica de direito público ou privado, independentemente do meio, do país de sua sede ou do país onde estejam localizados os dados, desde que:\\n\\nI - a operação de tratamento seja realizada no território nacional;\\n\\nI - a atividade de tratamento tenha por objetivo a oferta ou o fornecimento de bens ou serviços ou o tratamento de dados de indivíduos localizados no território nacional; ou III - os dados pessoais objeto do tratamento tenham sido coletados no território nacional.\\n\\n§ 1º Consideram-se coletados no território nacional os dados pessoais cujo titular nele se encontre no momento da coleta.\",\"o\":[],\"g\":2},{\"_id\":6,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"IBAMA Analista Ambiental Licenciamento Ambiental · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Dado com identificação genética ou biométrica de pessoas naturais é definido como dado\\npessoal sensível pela Lei n.º 13.709/2018.\",\"c\":\"O item está de acordo com a definição legal de dado sensível:\\n\\nart. 5º, II - Dado pessoal sensível: dado pessoal sobre origem racial ou étnica, convicção religiosa, opinião política, filiação a sindicato ou a organização de caráter religioso, filosófico ou político, dado referente à saúde ou à vida sexual, dado genético ou biométrico, quando vinculado a uma pessoa natural;\",\"o\":[],\"g\":2},{\"_id\":7,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"DPE RO Técnico da Defensoria Pública Técnico em Informática · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Segundo a Lei Geral de Proteção de Dados Pessoais, a pessoa natural ou jurídica a quem\\ncompete decisões referentes ao tratamento de dados pessoais é denominada\\n(A) titular.\\n\\n(B) autoridade.\\n\\n(C) controlador.\\n\\n(D) operador.\\n\\n(E) encarregado.\",\"c\":\"A letra (C) está correta, visto que o conceito apresentado é de controlador, sendo que as demais alternativas estão todas incorretas:\\n\\nArt. 5º Para os fins desta Lei, considera-se:\\n\\nVI - controlador: pessoa natural ou jurídica, de direito público ou privado, a quem competem as decisões referentes ao tratamento de dados pessoais;\\n\\nV - titular: pessoa natural a quem se referem os dados pessoais que são objeto de tratamento;\\n\\nVII - operador: pessoa natural ou jurídica, de direito público ou privado, que realiza o tratamento de dados pessoais em nome do controlador;\\n\\nVIII - encarregado: pessoa indicada pelo controlador e operador para atuar como canal de comunicação entre o controlador, os titulares dos dados e a Autoridade Nacional de Proteção de Dados (ANPD);\\n\\nXIX - autoridade nacional: órgão da administração pública responsável por zelar, implementar e fiscalizar o cumprimento desta Lei em todo o território nacional.\",\"o\":[],\"g\":2},{\"_id\":8,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"PGE RJ Analista Sistemas e Métodos · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados Pessoais), o encarregado\\ndeve realizar o tratamento de dados pessoais em nome do controlador, com o objetivo de\\nproteger os direitos fundamentais de privacidade.\",\"c\":\"Mais uma questão tentando confundir os conceitos de operador e encarregado:\\n\\nArt. 5º, VII – operador: pessoa natural ou jurídica, de direito público ou privado, que realiza o tratamento de dados pessoais em nome do controlador; VIII – encarregado: pessoa indicada pelo controlador e operador para atuar como canal de comunicação entre o controlador, os titulares dos dados e a Autoridade Nacional de Proteção de Dados (ANPD);\",\"o\":[],\"g\":4},{\"_id\":9,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"ICMBio Técnico Ambiental · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O tratamento de dados pessoais somente poderá ser realizado mediante o fornecimento de\\nconsentimento por seu titular, mesmo que este os tenha tornado manifestamente públicos.\",\"c\":\"Se o próprio titular do dado pessoal tornou-o público, não há que se falar em necessidade de seu consentimento para tratamento:\\n\\nArt. 7º, § 4º É dispensada a exigência do consentimento previsto no caput deste artigo para os dados tornados manifestamente públicos pelo titular, resguardados os direitos do titular e os princípios previstos nesta Lei.\",\"o\":[],\"g\":4},{\"_id\":10,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"ICMBio Técnico Ambiental · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Os dados pessoais serão eliminados após o término de seu tratamento, sendo autorizada a sua\\nconservação para a finalidade de estudo por órgão de pesquisa, bem como garantida, sempre\\nque possível, a anonimização desses dados.\",\"c\":\"Em regra, os dados pessoais serão eliminados após o término de seu tratamento, no âmbito e nos limites técnicos das atividades (art. 16). No entanto, pode ser autorizada a conservação dos dados pessoais (após o término do tratamento) para determinadas finalidades, entre elas o estudo por órgão de pesquisa:\\n\\nArt. 16. Os dados pessoais serão eliminados após o término de seu tratamento, no âmbito e nos limites técnicos das atividades, autorizada a conservação para as seguintes finalidades: (..)\\n\\nII - estudo por órgão de pesquisa, garantida, sempre que possível, a anonimização dos dados pessoais;\",\"o\":[],\"g\":2},{\"_id\":11,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TELEBRAS Especialista em Gestão de Telecomunicações Advogado · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Os dados pessoais de crianças poderão ser coletados sem consentimento dos pais ou do\\nresponsável legal quando for necessário para a proteção delas, hipótese em que tais dados\\npoderão, ainda, ser repassados a terceiros.\",\"c\":\"Em regra, exige-se o consentimento para tratamento de dados de crianças, sendo que tal consentimento deixa de ser exigido nas hipóteses de dado necessário para proteção da criança.\\n\\nTodavia, em nenhum caso será possível o repasse do dado a terceiro sem consentimento:\\n\\nArt. 14, § 1º O tratamento de dados pessoais de crianças deverá ser realizado com o consentimento específico e em destaque dado por pelo menos um dos pais ou pelo responsável legal.\\n\\n§ 3º Poderão ser coletados dados pessoais de crianças sem o consentimento a que se refere o § 1º deste artigo quando a coleta for necessária para contatar os pais ou o responsável legal, utilizados uma única vez e sem armazenamento, ou para sua proteção, e em nenhum caso poderão ser repassados a terceiro sem o consentimento de que trata o § 1º deste artigo.\",\"o\":[],\"g\":4},{\"_id\":12,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TELEBRAS Especialista em Gestão de Telecomunicações · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Anonimização dos dados pessoais é um direito do titular dos dados, que pode, ainda, requerer o\\nbloqueio ou a eliminação de dados desnecessários, excessivos ou tratados em desconformidade\\ncom o disposto na legislação de regência.\",\"c\":\"A anonimização, o bloqueio e a eliminação de dados desnecessários, excessivos ou tratados em desconformidade com o disposto nesta Lei é um dos direitos do titular dos dados:\\n\\nArt. 18, IV - anonimização, bloqueio ou eliminação de dados desnecessários, excessivos ou tratados em desconformidade com o disposto nesta Lei;\",\"o\":[],\"g\":2},{\"_id\":13,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TELEBRAS Advogado · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Em regra, a comunicação ou o uso compartilhado de dados pessoais de pessoa jurídica de\\ndireito público a pessoa de direito privado será informado à autoridade nacional e dependerá de\\nconsentimento do titular.\",\"c\":\"A assertiva está plenamente de acordo com o art. 27 da LGPD:\\n\\nArt. 27. A comunicação ou o uso compartilhado de dados pessoais de pessoa jurídica de direito público a pessoa de direito privado será informado à autoridade nacional e dependerá de consentimento do titular, exceto: (..)\",\"o\":[],\"g\":2},{\"_id\":14,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"TELEBRAS Advogado · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Em respeito aos princípios de proteção de dados pessoais, o uso compartilhado de dados\\npessoais pelo poder público deve atender a finalidades específicas de execução de políticas\\npúblicas.\",\"c\":\"A questão tem como fundamento o art. 26,caput, da LGPD, que reforça o princípio da finalidade (preceito geral da LGPD previsto em seu artigo 6º) também no uso compartilhado de dados pelo poder público:\\n\\nArt. 26. O uso compartilhado de dados pessoais pelo Poder Público deve atender a finalidades específicas de execução de políticas públicas e atribuição legal pelos órgãos e pelas entidades públicas, respeitados os princípios de proteção de dados pessoais elencados no art. 6º desta Lei.\",\"o\":[],\"g\":2},{\"_id\":15,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"BANESE Técnico Bancário I · 2021\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"É vedado ao poder público transferir a entidades privadas dados pessoais constantes na base de\\ndados a que ele tenha acesso, inclusive na hipótese de visar exclusivamente a prevenção de\\nfraudes e irregularidades.\",\"c\":\"Apesar de, em regra, o poder público estar proibido de transferir dados pessoais a entidades privadas, existem situações excepcionais em que será possível a transferência, como ocorre na hipótese de prevenção de fraudes e irregularidades:\\n\\nArt. 26, § 1º É vedado ao Poder Público transferir a entidades privadas dados pessoais constantes de bases de dados a que tenha acesso, exceto: (..)\\n\\nV - na hipótese de a transferência dos dados objetivar exclusivamente a prevenção de fraudes e irregularidades, ou proteger e resguardar a segurança e a integridade do titular dos dados, desde que vedado o tratamento para outras finalidades.\",\"o\":[],\"g\":4},{\"_id\":16,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"IBAMA Técnico Ambiental · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O operador que causar dano a outrem no desempenho da atividade de tratamento de dados\\npessoais, por descumprir as obrigações da legislação de proteção de dados, terá\\nresponsabilidade subsidiária ao controlador.\",\"c\":\"O item está incorreto, visto que a responsabilidade do operador será solidária com o controlador (e não subsidiária):\\n\\nArt. 42, §1º, I - o operador responde solidariamente pelos danos causados pelo tratamento quando descumprir as obrigações da legislação de proteção de dados ou quando não tiver seguido as instruções lícitas do controlador, hipótese em que o operador equipara-se ao controlador, salvo nos casos de exclusão previstos no art. 43 desta Lei;\",\"o\":[],\"g\":4},{\"_id\":17,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"FUNPRESP EXE Analista de Previdência Complementar Jurídica · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A obrigação de os agentes de tratamento de dados pessoais repararem dano patrimonial será\\nafastada se não houver violação à legislação de proteção de dados.\",\"c\":\"Exato, a questão traz corretamente uma das 3 hipóteses de afastamento da responsabilidade dos agentes de tratamento:\\n\\nArt. 43. Os agentes de tratamento só não serão responsabilizados quando provarem: I - que não realizaram o tratamento de dados pessoais que lhes é atribuído;\\n\\n- que, embora tenham realizado o tratamento de dados pessoais que lhes é\\n\\natribuído, não houve violação à legislação de proteção de dados; ou\\n\\n- que o dano é decorrente de culpa exclusiva do titular dos dados ou de terceiro.\",\"o\":[],\"g\":2},{\"_id\":18,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"DPE RO Analista da Defensoria Pública Programação · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com a Lei Geral de Proteção de Dados Pessoais, assinale a opção que indica quem\\ndeve comunicar à autoridade nacional a ocorrência de incidente de segurança relacionado a\\ndados pessoais que possa acarretar risco ou dano relevante.\\n\\n(A) titular\\n\\n\\n(B) segurança de TI\\n(C) operador\\n(D) controlador\\n(E) encarregado\",\"c\":\"O dever de realizar tal comunicação à ANPD e ao titular dos dados foi atribuído ao controlador:\\n\\nArt. 48. O controlador deverá comunicar à autoridade nacional e ao titular a ocorrência de incidente de segurança que possa acarretar risco ou dano relevante aos titulares.\",\"o\":[],\"g\":3},{\"_id\":19,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"IBAMA Técnico Ambiental · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Na aplicação da sanção de multa a agente de tratamento de dados, será considerada a condição\\neconômica dele.\",\"c\":\"A condição econômica do infrator será, sim, avaliada para definição das sanções a serem aplicadas:\\n\\nArt. 52, § 1º As sanções serão aplicadas após procedimento administrativo que possibilite a oportunidade da ampla defesa, de forma gradativa, isolada ou cumulativa, de acordo com as peculiaridades do caso concreto e considerados os seguintes parâmetros e critérios:\\n\\nI - a gravidade e a natureza das infrações e dos direitos pessoais afetados;\\n\\nII - a boa-fé do infrator;\\n\\nIII - a vantagem auferida ou pretendida pelo infrator;\\n\\nIV - a condição econômica do infrator;\\n\\nV - a reincidência;\\n\\nVI - o grau do dano;\\n\\nVII - a cooperação do infrator;\\n\\nVIII - a adoção reiterada e demonstrada de mecanismos e procedimentos internos capazes de minimizar o dano, voltados ao tratamento seguro e adequado de dados, em consonância com o disposto no inciso II do § 2º do art.\\n\\n48 desta Lei;\\n\\nIX- a adoção de política de boas práticas e governança;\\n\\nX - a pronta adoção de medidas corretivas; e XI - a proporcionalidade entre a gravidade da falta e a intensidade da sanção.\",\"o\":[],\"g\":2},{\"_id\":20,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"APEX Analista · 2022\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A Autoridade Nacional de Proteção de Dados (ANPD)\\n\\n(A) é entidade da administração pública federal com natureza jurídica de empresa pública.\\n\\n(B) é órgão com autonomia técnica, mas sem poder decisório.\\n\\n(C) prevê mandato dos membros do seu Conselho Diretor por, no máximo, dois anos.\\n\\n(D) é composta de corregedoria e ouvidoria.\",\"c\":\"A letra (A) está incorreta, pois tem natureza de autarquia.\\n\\nA letra (B) está incorreta, visto que possui autonomia técnica e poder decisório também.\\n\\nA letra (C) está incorreta, pois o mandato de seus membros é de 4 anos A letra (D) está correta, pois menciona dois órgãos que compõem a ANPD.\",\"o\":[],\"g\":3},{\"_id\":21,\"t\":\"Lei Geral de Proteção de Dados (LGPD — Lei 13.709/2018)\",\"b\":\"Cebraspe\",\"src\":\"ALECE Analista Legislativo Controle Interno · 2021\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No que diz respeito ao Conselho Nacional de Proteção de Dados Pessoais e da Privacidade, é\\ncorreto afirmar que\\n(A) sua composição conta com representação equânime de todos os poderes.\\n\\n(B) os representantes serão designados, por ato específico do chefe de cada poder, de acordo\\ncom a origem do indicado.\\n\\n(C) devem ser elaborados relatórios regionais acerca do nível de transparência e aplicação da\\npolítica de privacidade.\\n\\n(D) os representantes que compõem o referido conselho terão mandato de dois anos, permitida\\numa recondução.\\n\\n(E) devem ser elaborados estudos e realizados debates e audiências públicas sobre a proteção de\\ndados pessoais.\",\"c\":\"A letra (A) está incorreta, visto que a distribuição não é equânime entre os Poderes. A título de exemplo, dos 23 representantes, o Poder Executivo Federal conta com 5 e o Legislativo com apenas 2:\\n\\nArt. 58-A. O Conselho Nacional de Proteção de Dados Pessoais e da Privacidade será composto de 23 (vinte e três) representantes, titulares e suplentes, dos seguintes órgãos:\\n\\nI - 5 (cinco) do Poder Executivo federal; II - 1 (um) do Senado Federal;\\n\\nIII - 1 (um) da Câmara dos Deputados;\\n\\nA letra (B), incorreta, visto que serão todos designados pelo Presidente da República:\\n\\nArt. 58-A, § 1º Os representantes serão designados por ato do Presidente da República, permitida a delegação.\\n\\nA letra (C), incorreta, visto que tais relatórios dizem respeito a uma política nacional (e não regional):\\n\\nII - elaborar relatórios anuais de avaliação da execução das ações da Política Nacional de Proteção de Dados Pessoais e da Privacidade;\\n\\nA letra (D) está incorreta por um detalhe sutil: o prazo de 2 anos aplica-se apenas aos representantes \\\"não governamentais\\\" do CNPD:\\n\\nArt. 58-A, § 3º Os representantes de que tratam os incisos VII, VIII, IX, X e XI do caput deste artigo e seus suplentes [de entidades da sociedade civil, de instituições científicas, tecnológicas e de inovação, de confederações sindicais, de entidades representativas do setor empresarial e de entidades representativas do setor laboral]:\\n\\n- serão indicados na forma de regulamento;\\n\\n- não poderão ser membros do Comitê Gestor da Internet no Brasil; III - terão\\n\\nmandato de 2 (dois) anos, permitida 1 (uma) recondução.\\n\\nA letra (E), correta, de acordo com a lista de competências do CNPD:\\n\\nArt. 58-B, IV - elaborar estudos e realizar debates e audiências públicas sobre a proteção de dados pessoais e da privacidade; e\",\"o\":[],\"g\":4}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Direito Administrativo::Aula 15":{"questoesPdf":[{"title":"Questões Extraídas — Código de Ética (Decreto 1.171/94) · Aula 15 (80 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Direito Administrativo Aula 15 — Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">DIREITO ADMINISTRATIVO · AULA 15 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Direito Administrativo · Aula 15 — <b>Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Direito Administrativo · Aula 15 — questões extraídas do PDF (Prof. Herbert Almeida · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"PE IF · 2016\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com o Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal -\\nDecreto 1.171 de 22/06/1994 - XV é vedado ao agente público do Ministério da Previdência Social -\\nMPS - além dos previstos no Art. 117, da Lei no 8.112/90. Assinale a alternativa CORRETA.\",\"c\":\"Perceba que a questão nos pede para marcarmos a alternativa que corresponde a uma vedação imposta ao servidor pelo Decreto n. 1.171/1994. Nossa resposta é a alternativa A, pois nas vedações que constam no inciso XV temos aquela relacionada ao uso de informações privilegiadas em benefício do próprio servidor ou de terceiros.\\n\\nXV - E vedado ao servidor público;\\n\\nm) fazer uso de informações privilegiadas obtidas no âmbito interno de seu serviço, em benefício próprio, de parentes, de amigos ou de terceiros;\\n\\nAs alternativas B, C e E não são propriamente proibições, e sim deveres, não é mesmo!? Basta uma leitura atenta para que você não caia nessa pegadinha...!\\n\\nQuando à alternativa D, não há nada parecido com isso no Código de Ética, e não faria muito sentido haver.\\n\\nImagine se você não pudesse comprar uma caneta de determinado fornecedor porque ele vende para a Administração Pública. Não faz nenhum sentido, não é mesmo!?\",\"o\":[\"Alienar, comprar, investir ou praticar outros atos de gestão de bens próprios ou de terceiros, com base em informação governamental da qual tenha conhecimento privilegiado.\",\"Manter sigilo quanto às informações sobre ato, fato ou decisão não divulgáveis ao público, ressalvando os casos cuja divulgação seja exigida em norma.\",\"Exercer juízo profissional independente, mantendo imparcialidade no tratamento com o público e com os demais agentes.\",\"Comprar ou adquirir bens e serviços de organizações privadas que tenham contratos com Órgãos Públicos.\",\"Reconhecer, quando no exercício de cargo de chefia, o mérito de cada agente e propiciar igualdade de oportunidades para o desenvolvimento profissional.\"],\"g\":0},{\"_id\":1,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"PE IF · 2016\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O Decreto n° 1.171/94 contempla informações sobre o comportamento profissional e atitudes no\\nserviço público. Acerca do tema, assinale a alternativa CORRETA.\",\"c\":\"A alternativa A está incorreta. Nos termos do inciso III das regras deontológicas, a moralidade da Administração Pública não se limita à distinção entre o bem e o mal, devendo ser acrescida da ideia de que o fim é sempre o bem comum, independente dos meios para alcançá-lo.\\n\\nA alternativa B está correta e é a nossa resposta. Nos termos do inciso VI, a função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular de cada servidor público. Assim, os fatos e atos verificados na conduta do dia a dia em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\\n\\nA alternativa C está incorreta. É é dever do servidor público comunicar a seus superiores todo e qualquer ato ou fato contrário ao interesse público, exigindo as providências cabíveis, conforme previsão do inciso XIV, “m”.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\nm) comunicar imediatamente a seus superiores todo e qualquer ato ou fato contrário ao interesse público, exigindo as providências cabíveis;\\n\\nA alternativa D está incorreta. D - ERRADA - O servidor público não pode pleitear, solicitar, provocar, sugerir ou receber qualquer tipo de ajuda financeira, gratificação, prêmio, comissão, doação ou vantagem de qualquer espécie para si, de acordo com o inciso XV, “g”.\\n\\nXV - E vedado ao servidor público;\\n\\nAula 15 - Legislação\\n\\ng) pleitear, solicitar, provocar, sugerir ou receber qualquer tipo de ajuda financeira, gratificação, prêmio, comissão, doação ou vantagem de qualquer espécie, para si, familiares ou qualquer pessoa, para o cumprimento da sua missão ou para influenciar outro servidor para o mesmo fim;\\n\\nA alternativa E está incorreta. De acordo com o inciso XVI, em todos os órgãos e entidades da Administração Pública Federal direta, indireta autárquica e fundacional, ou em qualquer órgão ou entidade que exerça atribuições delegadas pelo poder público, deverá ser criada uma Comissão de Ética.\",\"o\":[\"A moralidade da Administração Pública se limita à distinção entre o bem e o mal, devendo ser acrescida da ideia de que o fim é sempre o bem comum, independente dos meios para alcançá-lo.\",\"A função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular de cada servidor público. Assim, os fatos e atos verificados na conduta do dia a dia em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\",\"Não é dever do servidor público comunicar a seus superiores todo e qualquer ato ou fato contrário ao interesse público, exigindo as providências cabíveis.\",\"O servidor público, desde que autorizado por sua chefia direta, pode pleitear, solicitar, provocar, sugerir ou receber qualquer tipo de ajuda financeira, gratificação, prêmio, comissão, doação ou vantagem de qualquer espécie para si.\",\"Apenas alguns órgãos e entidades da Administração Pública Federal Direta devem ter Comissão de Ética, encarregada de orientar e aconselhar sobre a ética profissional do servidor, no tratamento com as pessoas e com o patrimônio público.\"],\"g\":1},{\"_id\":2,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"PE IF · 2013\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal, aprovado através\\ndo Decreto nº 1.171, de 22/06/94, representa um importante instrumento de orientação no que diz\\nrespeito à conduta dos servidores. Em relação aos deveres fundamentais do servidor público, analise\\nas afirmações a seguir:\\n\\nI. desempenhar, a tempo, as atribuições do cargo, função ou emprego público, mesmo dos quais não\\nseja titular, sempre que solicitado.\\n\\nII. somente admitir o retardo de prestação de contas em situações que exijam, tais como dificuldades\\nde junção de documentos;\\n\\nIII. tratar cuidadosamente os usuários dos serviços, aperfeiçoando o processo de comunicação e\\ncontato com o público;\\n\\nIV. ter consciência de que seu trabalho é regido por princípios éticos que se materializam na adequada\\nprestação dos serviços públicos;\\n\\nV. comunicar imediatamente a seus superiores todo e qualquer ato ou fato contrário ao interesse\\npúblico, exigindo as providências cabíveis.\\n\\nEstá CORRETO o que se afirma APENAS em\",\"c\":\"Nesta questão temos erros nos itens I e II.\\n\\nO item I está incorreto porque diz que o servidor deveria exercer as funções equivalentes a cargo do qual não é titular. Isso seria usurpação de função, não é mesmo!?\\n\\nO item II está incorreto porque traz a possibilidade de o servidor retardar a prestação de contas, o que não é permitido pelo Código de Ética.\\n\\nAula 15 - Legislação\",\"o\":[\"I, II e V.\",\"I, III e V.\",\"II, III e V.\",\"II, III e IV.\",\"III, IV e V.\"],\"g\":4},{\"_id\":3,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"PE IF · 2013\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Em relação ao Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal, analise\\nas afirmações:\\n\\nI. A moralidade da Administração Pública não se limita à distinção entre o bem e o mal, devendo ser\\nacrescida da ideia de que o fim é sempre o bem comum. O necessário predomínio da legalidade sobre\\na finalidade, na conduta do servidor público, é que poderá consolidar o respeito ao bem comum no\\nato administrativo.\\n\\nII. A remuneração do servidor público é custeada pelos tributos pagos direta ou indiretamente por\\ntodos, até por ele próprio, e por isso se exige, como contrapartida, que a moralidade administrativa se\\nintegre no Direito, como elemento indissociável de sua aplicação e de sua finalidade, erigindo-se, como\\nconsequência, em fator de legalidade.\\n\\nIII. Deixar o servidor público qualquer pessoa à espera de solução que compete ao setor em que exerça\\nsuas funções, permitindo a formação de longas filas, ou qualquer outra espécie de atraso na prestação\\ndo serviço, não caracteriza apenas atitude contra a ética ou ato de desumanidade, mas principalmente\\ngrave dano moral aos usuários dos serviços públicos.\\n\\nIV. O servidor deve prestar toda a sua atenção às ordens de seus superiores, buscando atentamente o\\nseu cumprimento, e, assim, evitando a conduta de insubordinação. Os repetidos erros, o descaso e o\\nacúmulo de desvios tornam-se permanentes dificuldades da obediência no desempenho da função\\npública.\\n\\nEstá CORRETO o que se afirma APENAS em\",\"c\":\"O item I se refere ao inciso III do Código e Ética e está incorreto. Não há predomínio da legalidade, mas sim o equilíbrio entre legalidade e finalidade.\\n\\nO item II está correto, reproduzindo o inciso IV do Código de Ética.\\n\\nO item III também está correto, reproduzindo o inciso X.\\n\\nO item IV está incorreto. De acordo com o inciso XI, o servidor deve prestar toda a sua atenção às ordens legais de seus superiores, velando atentamente por seu cumprimento, e, assim, evitando a conduta negligente. Os repetidos erros, o descaso e o acúmulo de desvios tornam-se, às vezes, difíceis de corrigir e caracterizam até mesmo imprudência no desempenho da função pública.\\n\\nAula 15 - Legislação\",\"o\":[\"I, III e IV.\",\"II, III e IV.\",\"II e III.\",\"I, II e III.\",\"I e IV.\"],\"g\":2},{\"_id\":4,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Depen · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No que se refere a ética e moral, julgue o item subsecutivo.\\n\\nAs decisões tomadas por um servidor com base no código de ética profissional do servidor público\\ndevem ser pautadas na legalidade, moralidade, conveniência e oportunidade, ao passo que aspectos\\nsubjetivos da personalidade dos indivíduos, como honestidade e desonestidade e o bem e o mal, não\\nsão passíveis de apreciação.\",\"c\":\"Já começamos com uma questão polêmica! Veja bem, os princípios mencionados pela assertiva (legalidade, moralidade, conveniência e oportunidade) certamente devem orientar a atuação do servidor público.\\n\\nVejamos o que diz o inciso II do Código de Ética.\\n\\nII - O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim, não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto, consoante as regras contidas no art. 37, caput, e § 4°, da Constituição Federal.\\n\\nA banca fez, na minha opinião, uma lambança quando passou a mencionar os aspectos subjetivos da personalidade dos indivíduos. Esses aspectos subjetivos são importantes para avaliar a conduta do servidor, mas não a do cidadão que busca o serviço público. Do jeito que a assertiva foi escrita, isso não ficou muito claro, e por isso quem tem familiaridade com o Código de Ética e sabe que ele fala em honestidade e desonestidade, por exemplo, poderia terminar errando a questão. Apesar de ter sido mal formulada, essa questão não foi anulada pela banca examinadora, e o gabarito é certo.\",\"g\":\"C\"},{\"_id\":5,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Depen · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No que se refere a ética e moral, julgue o item subsecutivo.\\n\\nDe acordo com o Decreto n.º 1.171/1994, a moralidade da administração pública fundamenta-se na\\ndistinção entre o bem e o mal e na ideia de que o fim é sempre o bem comum, devendo a conduta do\\nservidor público ater-se à busca do equilíbrio entre legalidade e finalidade.\",\"c\":\"Esta questão cobra o conhecimento do inciso III do Código de Ética, e exige que o candidato saiba interpretar bem o texto.\\n\\nIII - A moralidade da Administração Pública não se limita à distinção entre o bem e o mal, devendo ser acrescida da idéia de que o fim é sempre o bem comum. O equilíbrio entre a legalidade e a finalidade, na conduta do servidor público, é que poderá consolidar a moralidade do ato administrativo\\n\\nAula 15 - Legislação\\n\\nA questão diz que a moralidade se fundamenta na distinção entre o bem e o mal, e isso é correto, apesar de sabermos que a noção de moralidade na Administração Pública deve ir além disso, pautando-se pelo bem comum.\",\"g\":\"C\"},{\"_id\":6,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Depen · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No que se refere a ética e moral, julgue o item subsecutivo.\\n\\nSITUAÇÃO HIPOTÉTICA: Bruno, servidor público federal, teve de cumprir suas atividades diárias após o\\nhorário do expediente devido ao fato de ter se prontificado, durante o dia, a auxiliar um colega de\\noutro setor em uma atividade de caráter emergencial.\\n\\nASSERTIVA: Nessa situação, Bruno agiu em consonância com a conduta ética que se espera do servidor\\npúblico, já que, ao ter auxiliado o colega e ainda ter finalizado suas atividades diárias depois do\\nexpediente, ele fez mais do que sua função lhe exigia.\",\"c\":\"Se você responder essa questão apenas com base no “feeling”, provavelmente vai acertar. A conduta de auxiliar o colega que está precisando de ajuda em caráter emergencial é desejável, e por isso Bruno agiu eticamente. O Código de Ética não traz dispositivos expressos no sentido de que se espera do servidor que permaneça no serviço nessas situações, mas veja, por exemplo, que diz o inciso V.\\n\\nV - O trabalho desenvolvido pelo servidor público perante a comunidade deve ser entendido como acréscimo ao seu próprio bem-estar, já que, como cidadão, integrante da sociedade, o êxito desse trabalho pode ser considerado como seu maior patrimônio.\",\"g\":\"C\"},{\"_id\":7,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MPU · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considerando as disposições do Decreto n.º 1.171/1994 e as resoluções da Comissão de Ética Pública\\nda Presidência da República (CEP), julgue o item a seguir.\\n\\nÉ vedado ao servidor público, conforme o Decreto n.º 1.171/1994, retirar da repartição pública\\nqualquer documento pertencente ao patrimônio público, salvo se estiver legalmente autorizado a fazê-\\nlo.\",\"c\":\"O Código de Ética traz uma série de proibições aplicáveis ao servidor público, entre elas a descrita pela questão.\\n\\nXV - E vedado ao servidor público;\\n\\n[...]\\n\\nl) retirar da repartição pública, sem estar legalmente autorizado, qualquer documento, livro ou bem pertencente ao patrimônio público;\\n\\nAula 15 - Legislação\",\"g\":\"C\"},{\"_id\":8,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MPU · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considerando as disposições do Decreto n.º 1.171/1994 e as resoluções da Comissão de Ética Pública\\nda Presidência da República (CEP), julgue o item a seguir.\\n\\nNão atentará contra os deveres fundamentais do servidor público, previstos no Decreto n.º\\n1.171/1994, o servidor público federal que, mesmo exercendo a sua função com finalidade estranha\\nao interesse público, atue em conformidade com as formalidades legais e não viole expressamente\\ndisposições de lei.\",\"c\":\"Um dos deveres fundamentais do servidor público é abster-se de exercer sua função, poder ou autoridade com finalidade estranha ao interesse público. Vejamos o que diz o inciso XIV, “u”.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nu) abster-se, de forma absoluta, de exercer sua função, poder ou autoridade com finalidade estranha ao interesse público, mesmo que observando as formalidades legais e não cometendo qualquer violação expressa à lei;\\n\\nSe o servidor agir com finalidade estranha ao serviço público, portanto, estará incorrendo em proibição imposta pelo Código de Ética, e por isso estará atentando contra os deveres funcionais.\",\"g\":\"E\"},{\"_id\":9,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MPU · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Acerca de ética e função pública, julgue os item que se segue.\\n\\nPara que a conduta do servidor público seja considerada irrepreensível é suficiente que ele observe as\\nleis e as regras imperativas.\",\"c\":\"Veja bem, o Código de Ética estabelece para o servidor público valores que vão muito além da legalidade.\\n\\nVamos relembrar o que diz o inciso II.\\n\\nII - O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim, não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto, consoante as regras contidas no art. 37, caput, e § 4°, da Constituição Federal.\\n\\nPara ser considerada irrepreensível, portanto, a conduta do servidor deverá ir muito além da legalidade, pautando-se também pela conveniência, oportunidade e honestidade.\",\"g\":\"E\"},{\"_id\":10,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TRE · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Acerca da ética no serviço público, cada um dos itens que se seguem apresenta uma situação\\nhipotética, seguida de uma assertiva a ser julgada.\\n\\nRodrigo, servidor público, tem o hábito de consumir bebida alcoólica em excesso em bares e\\nrestaurantes da cidade duas ou três vezes por semana após seu horário de trabalho, ocasiões em que\\nfica bastante embriagado. Nessa situação, ainda que a embriaguez habitual ocorra fora do ambiente\\ndo trabalho, a conduta de Rodrigo fere dispositivo do Código de Ética dos Servidores Públicos.\",\"c\":\"Aqui é útil relembrarmos o inciso I do Código de Ética.\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos.\\n\\nPerceba que há conceitos abertos aqui, como dignidade e decoro, que devem nortear a conduta do servidor público, mesmo fora do ambiente de trabalho.\\n\\nA resposta definitiva para a nossa questão, porém, está nas proibições impostas pelo Código de Ética ao servidor público, que se encontram no inciso XV.\\n\\nXV - E vedado ao servidor público:\\n\\nn) apresentar-se embriagado no serviço ou fora dele habitualmente;\\n\\nA proibição de apresentar-se embriagado habitualmente se estende também a ambientes externos ao serviço, e por isso Rodrigo incorre em proibição ao Código de Ética.\",\"g\":\"C\"},{\"_id\":11,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TRE · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No que se refere à ética no serviço público, julgue o item a seguir.\\n\\nConsidere que um servidor público tenha deixado, sem justo motivo, muitas pessoas à espera de\\nsolução que compete ao setor em que exerça suas funções, o que resultou na formação de longas filas\\ne atraso na prestação do serviço. Nessa situação, a atitude do servidor, além de ter sido contra a ética,\\npode ser caracterizada como de grave dano moral aos usuários do serviço público.\",\"c\":\"Deixar pessoas aguardando providências sem justificativa é uma conduta grave, causadora de dano moral, especificamente prevista no Código de Ética.\\n\\nX - Deixar o servidor público qualquer pessoa à espera de solução que compete ao setor em que exerça suas funções, permitindo a formação de longas filas, ou qualquer outra espécie de atraso\\n\\nAula 15 - Legislação\\n\\nna prestação do serviço, não caracteriza apenas atitude contra a ética ou ato de desumanidade, mas principalmente grave dano moral aos usuários dos serviços públicos.\",\"g\":\"C\"},{\"_id\":12,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TRE · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Acerca da ética no serviço público, cada item que se segue apresenta uma situação hipotética, seguida\\nde uma assertiva a ser julgada.\\n\\nMirtes, que é servidora pública com mais de vinte anos de ofício em um TRE, acostumou-se com a\\nforma tradicional de realizar suas tarefas e, por isso, se recusa a utilizar os sistemas eletrônicos\\ninstitucionais que foram instalados em seu departamento. Nessa situação, a chefia imediata de Mirtes\\ndeve adaptar a rotina de trabalho para que ela possa continuar a trabalhar da forma que lhe é mais\\nconveniente em respeito a sua longa carreira no tribunal.\",\"c\":\"Isso não tem o menor cabimento, não é mesmo!? Um servidor não pode simplesmente recusar-se a acompanhar a evolução da tecnologia no trabalho. Essa servidora incorre claramente numa das proibições previstas no Código de Ética.\\n\\nXV - E vedado ao servidor público:\\n\\n[...]\\n\\ne) deixar de utilizar os avanços técnicos e científicos ao seu alcance ou do seu conhecimento para\\n\\natendimento do seu mister;\",\"g\":\"E\"},{\"_id\":13,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCE · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A comissão de ética é encarregada de orientar e aconselhar o servidor acerca das regras de conduta\\nético-profissional concernentes ao tratamento com as pessoas e com o patrimônio público. Além disso,\\ncabe à referida comissão competência para exonerar o servidor que desrespeitar essas normas.\",\"c\":\"A Comissão de Ética deve, nos termos do Decreto nº 1.171/1994, “orientar e aconselhar sobre a ética profissional do servidor, no tratamento com as pessoas e com o patrimônio público, competindo-lhe conhecer concretamente de imputação ou de procedimento susceptível de censura”.\\n\\nNão cabe de forma alguma à Comissão de Ética, porém, exonerar o servidor. A única penalidade aplicada por este órgão é a censura ética.\",\"g\":\"E\"},{\"_id\":14,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCE · 2015\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Aula 15 - Legislação\\n\\nO servidor público deve privar-se do cumprimento de função, poder ou autoridade que apresente\\nfinalidade estranha ao interesse público, salvo se observar as formalidades legais.\",\"c\":\"Mais uma vez surge aqui a necessidade de observar a finalidade do serviço público, que nada mais é do que o próprio interesse público. Se o servidor estiver agindo com outra finalidade, de nada adianta estar cumprindo todos os preceitos legais.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nu) abster-se, de forma absoluta, de exercer sua função, poder ou autoridade com finalidade estranha ao interesse público, mesmo que observando as formalidades legais e não cometendo qualquer violação expressa à lei;\",\"g\":\"E\"},{\"_id\":15,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Antaq · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A função pública representa exercício profissional do servidor, não devendo integrar-se à vida\\nparticular do servidor público.\",\"c\":\"Quando o Código de Ética define a função pública, faz relação com o exercício profissional, integrando- a à vida privada do servidor. Vejamos o que diz o inciso VI do Código de Ética.\\n\\nVI - A função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular de cada servidor público. Assim, os fatos e atos verificados na conduta do dia-a-dia em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\",\"g\":\"E\"},{\"_id\":16,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Antaq · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"É vedado ao servidor público desviar outros servidores para atender a seus interesses particulares,\\nexceto em casos que envolvam risco da imagem do servidor ou da organização.\",\"c\":\"Se você já tem alguma experiência e concursos públicos, deve ter achado essa exceção meio estranh a, não é mesmo!? Na realidade o Código de Ética proíbe que o servidor público desvie outro servidor para atender interesse particular, não estabelecendo qualquer exceção.\\n\\nXV - E vedado ao servidor público:\\n\\n[...]\\n\\nj) desviar servidor público para atendimento a interesse particular;\",\"g\":\"E\"},{\"_id\":17,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Antaq · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Ser assíduo e frequente ao serviço não é um dos principais deveres do servidor público, caso este\\ndesempenhe bem e a tempo as atribuições do cargo, função ou emprego público de que seja titular.\",\"c\":\"Ser assíduo e frequente ao serviço é um dos deveres do servidor público previstos no inciso XIV do Decreto nº 1.171/1994.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nl) ser assíduo e frequente ao serviço, na certeza de que sua ausência provoca danos ao trabalho ordenado, refletindo negativamente em todo o sistema;\\n\\nAlém de desempenhar bem as atribuições do cargo, portanto, o servidor precisa ser assíduo e frequente.\",\"g\":\"E\"},{\"_id\":18,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Antaq · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A comissão de ética poderá aplicar ao servidor público que descumprir dever ético pena de advertência\\ne, no caso de reincidência, censura ética, sendo necessário parecer assinado pelo presidente da\\ncomissão.\",\"c\":\"A Comissão de Ética só aplica uma penalidade, que é a censura ética, nos termos do inciso XVI do Código de Ética.\\n\\nXVI - Em todos os órgãos e entidades da Administração Pública Federal direta, indireta autárquica e fundacional, ou em qualquer órgão ou entidade que exerça atribuições delegadas pelo poder público, deverá ser criada uma Comissão de Ética, encarregada de orientar e aconselhar sobre a ética profissional do servidor, no tratamento com as pessoas e com o patrimônio público, competindo-lhe conhecer concretamente de imputação ou de procedimento susceptível de censura.\\n\\nVemos, portanto, que não há advertência, o que já torna a assertiva errada. A questão do parecer, por sua vez, é esclarecida pelo inciso XXII.\\n\\nXXII - A pena aplicável ao servidor público pela Comissão de Ética é a de censura e sua fundamentação constará do respectivo parecer, assinado por todos os seus integrantes, com ciência do faltoso.\\n\\nComo o parecer é assinado por todos os integrantes da Comissão, está aí mais um erro da questão.\",\"g\":\"E\"},{\"_id\":19,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Antaq · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"É dever do servidor público respeitar a hierarquia, não podendo representar em hipótese alguma,\\ncontra qualquer comprometimento indevido da estrutura em que se funda o poder estatal.\",\"c\":\"O respeito à hierarquia certamente é um importante dever do servidor público, mas tal dever encontra limites justamente diante das situações de comprometimento indevido da estrutura.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nh) ter respeito à hierarquia, porém sem nenhum temor de representar contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal;\",\"g\":\"E\"},{\"_id\":20,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Anatel · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação ao comportamento profissional do servidor previsto no Código de Ética Profissional do\\nServidor Público Civil do Poder Executivo Federal, julgue o item subsequente.\\n\\nToda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço\\npúblico, podendo conduzir à desordem nas relações humanas.\",\"c\":\"Esta questão reproduz quase literalmente o conteúdo do inciso XII do Decreto nº 1.171/1994.\\n\\nXII - Toda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço público, o que quase sempre conduz à desordem nas relações humanas.\",\"g\":\"C\"},{\"_id\":21,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Anatel · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação ao comportamento profissional do servidor previsto no Código de Ética Profissional do\\nServidor Público Civil do Poder Executivo Federal, julgue o item subsequente.\\n\\nÉ vedado ao servidor público manter-se habitualmente embriagado, ainda que fora do serviço.\",\"c\":\"Aqui é útil relembrarmos o inciso I do Código de Ética.\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos.\\n\\nAula 15 - Legislação\\n\\nPerceba que há conceitos abertos aqui, como dignidade e decoro, que devem nortear a conduta do servidor público, mesmo fora do ambiente de trabalho.\\n\\nA resposta definitiva para a nossa questão, porém, está nas proibições impostas pelo Código de Ética ao servidor público, que se encontram no inciso XV.\\n\\nXV - E vedado ao servidor público:\\n\\nn) apresentar-se embriagado no serviço ou fora dele habitualmente;\\n\\nA proibição de apresentar-se embriagado habitualmente se estende também a ambientes externos ao serviço, e por isso a assertiva está certa.\",\"g\":\"C\"},{\"_id\":22,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCDF · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Ao servidor público que ocupa cargo de chefia é permitido, em situações especiais, determinar que\\nservidor a ele subordinado seja desviado de função para atender a interesse particular daquele, caso\\no ato não implique prejuízo do desempenho das atividades do serviço público.\",\"c\":\"Mais uma vez aparece aqui essa exceção esquisita, não é!? Na realidade o Código de Ética proíbe que o servidor público desvie outro servidor para atender interesse particular, não estabelecendo qualquer exceção.\\n\\nXV - E vedado ao servidor público:\\n\\n[...]\\n\\nj) desviar servidor público para atendimento a interesse particular;\",\"g\":\"E\"},{\"_id\":23,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considere um servidor que cumpre com atenção e cuidado suas atividades no ambiente de trabalho,\\nmas que, fora dele, mantém seu nome vinculado a empreendimentos de cunho duvidoso. Nesse caso,\\né correto afirmar que a conduta desse servidor fere a ética do serviço público.\",\"c\":\"Exercer atividade profissional aética ou ligar o seu nome a empreendimentos de cunho duvidoso é uma das condutas proibidas pelo Código de Ética.\\n\\nXV - E vedado ao servidor público:\\n\\n[...]\\n\\np) exercer atividade profissional aética ou ligar o seu nome a empreendimentos de cunho duvidoso.\\n\\nAula 15 - Legislação\",\"g\":\"C\"},{\"_id\":24,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Procurar manter uma boa comunicação com os usuários da repartição constitui característica de\\nconduta ética.\",\"c\":\"Um dos deveres fundamentais descritos no inciso XIV do Código de Ética diz respeito à comunicação com os usuários do serviço público.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\ne) tratar cuidadosamente os usuários dos serviços aperfeiçoando o processo de comunicação e\\n\\ncontato com o público;\",\"g\":\"C\"},{\"_id\":25,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Caso um servidor, preocupado com o bem estar dos usuários os quais atende, opte por ocultar uma\\ndecisão oficial que contraria os interesses de determinado usuário, ele será considerado um servidor\\ncompromissado eticamente com seu serviço e com sua relação com o público.\",\"c\":\"Isso não faria o menor sentido, não é mesmo!? O servidor não deve ocultar a verdade, ainda que ela seja contrária aos interesses do interessado. Vejamos o que diz o inciso VIII do Código de Ética.\\n\\nVIII - Toda pessoa tem direito à verdade. O servidor não pode omiti-la ou falseá-la, ainda que contrária aos interesses da própria pessoa interessada ou da Administração Pública. Nenhum Estado pode crescer ou estabilizar-se sobre o poder corruptivo do hábito do erro, da opressão ou da mentira, que sempre aniquilam até mesmo a dignidade humana quanto mais a de uma Nação.\",\"g\":\"E\"},{\"_id\":26,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Exerce seu dever de cidadania, em conformidade com os padrões éticos aceitos, o servidor público que\\nnão se deixa corromper e denuncia todos os atos de corrupção de que toma conhecimento.\",\"c\":\"Perfeito! O Código de Ética define como dever do servidor a resistência a todas pressões, nos termos do inciso XVI, “i”. Além disso, o servidor deve sempre denunciar essas pressões.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\ni) resistir a todas as pressões de superiores hierárquicos, de contratantes, interessados e outros que visem obter quaisquer favores, benesses ou vantagens indevidas em decorrência de ações imorais, ilegais ou aéticas e denunciá-las;\\n\\nAula 15 - Legislação\",\"g\":\"C\"},{\"_id\":27,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O servidor que, para algumas situações de trabalho, avalia com cuidado qual a melhor maneira de agir\\npara alcançar os resultados esperados e se orienta por princípios de justiça, está em concordância com\\na ética.\",\"c\":\"Se você leu essa assertiva rapidamente, provavelmente errou a resposta. Veja bem, a assertiva diz que o servidor deve avaliar com cuidado qual a melhor maneira de agir para alcançar os resultados esperados e se orientar por princípios de justiça. Ótimo, não é mesmo!? Só que a assertiva diz que isso deve ocorrer em apenas algumas situações, e aí é que está o pulo do gato, pois o servidor deve se orientar por esses princípios sempre!\",\"g\":\"E\"},{\"_id\":28,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O servidor que é visto habitualmente embriagado fora de seu horário de expediente, mas cumpre suas\\natividades com esmero durante seu horário de trabalho não fere a ética do serviço público.\",\"c\":\"A essa altura você já deve estar cansado de saber que a embriaguez habitual mesmo fora do serviço é uma conduta proibida pelo Código de Ética, não é mesmo!?\\n\\nXV - E vedado ao servidor público:\\n\\nn) apresentar-se embriagado no serviço ou fora dele habitualmente;\",\"g\":\"E\"},{\"_id\":29,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ICMBio · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considere que um servidor, ao atender um usuário, tenha-o deixado esperando por muito tempo, fato\\nque resultou na formação de uma longa fila em seu setor. Nesse caso, como o servidor se prestou a\\nbuscar informações benéficas para o usuário, primando pela precisão de seu trabalho, acima da\\nceleridade, ele não feriu o Código de Ética do Servidor Público do Poder Executivo Federal.\",\"c\":\"Esta questão gerou alguma polêmica, pois relata uma situação em que o servidor, na intenção de atender bem ao usuário do serviço público, terminou demorando muito. Pois bem, o zelo no atendimento prestado é um princípio que deve ser observado, e está no inciso I do Código de Ética.\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele,\\n\\nAula 15 - Legislação\\n\\njá que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos.\\n\\nAcontece que a celeridade também deve ser observada, e por isso o servidor não pode colocar um dever sobre o outro, e por isso a assertiva terminou sendo dada como errada.\\n\\nX - Deixar o servidor público qualquer pessoa à espera de solução que compete ao setor em que exerça suas funções, permitindo a formação de longas filas, ou qualquer outra espécie de atraso na prestação do serviço, não caracteriza apenas atitude contra a ética ou ato de desumanidade, mas principalmente grave dano moral aos usuários dos serviços públicos.\\n\\nApesar de algumas reclamações, não houve mudança de gabarito por parte da banca.\",\"g\":\"E\"},{\"_id\":30,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCDF · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Servidor público que não participa de atividades de atualização de seus conhecimentos, para o\\nexercício de suas atribuições, infringe os deveres do servidor.\",\"c\":\"A atualização do servidor é um dos deveres previstos no Código de Ética.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nq) manter-se atualizado com as instruções, as normas de serviço e a legislação pertinentes ao órgão onde exerce suas funções;\\n\\nA assertiva, portanto, é certa.\",\"g\":\"C\"},{\"_id\":31,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCDF · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A conduta de uma servidora pública que aja sempre com eficácia, zelo, dignidade, decoro e consciência\\ndos princípios morais contribui para a preservação da honra e da tradição dos serviços públicos.\",\"c\":\"Essa assertiva foi escrita reproduzindo o conteúdo do inciso I do Código de Ética. Numa leitura atenta você já saberia com tranquilidade que ela está correta, pois faz todo sentido.\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos.\",\"g\":\"C\"},{\"_id\":32,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCDF · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A ética no serviço público exige que seus servidores tratem o serviço como parte de sua carreira\\nprofissional, separando-o, portanto, de sua vida privada, e que abdiquem de seus interesses pessoais\\nem função dos interesses públicos, sempre que necessário.\",\"c\":\"A conduta do servidor no serviço público se integra à sua vida privada, nos termos do inciso VI do Código de Ética.\\n\\nVI - A função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular de cada servidor público. Assim, os fatos e atos verificados na conduta do dia-a-dia em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\\n\\nA assertiva, portanto, está errada.\",\"g\":\"E\"},{\"_id\":33,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TCDF · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Caso um servidor público, levando em conta os interesses da administração pública, omita um fato a\\num usuário da instituição em que trabalha, essa conduta não infringirá a ética do serviço público, que\\nprima pelos interesses públicos em vez dos particulares.\",\"c\":\"A omissão de informações ao usuário é totalmente contrária aos preceitos do Código de Ética.\\n\\nVIII - Toda pessoa tem direito à verdade. O servidor não pode omiti-la ou falseá-la, ainda que contrária aos interesses da própria pessoa interessada ou da Administração Pública. Nenhum Estado pode crescer ou estabilizar-se sobre o poder corruptivo do hábito do erro, da opressão ou da mentira, que sempre aniquilam até mesmo a dignidade humana quanto mais a de uma Nação.\\n\\nPerceba que o Código de Ética é claro no sentido de que o usuário deve receber as informações necessárias, ainda que elas contrariem os interesses da própria Administração Pública. A assertiva, portanto, está errada.\",\"g\":\"E\"},{\"_id\":34,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Funrio Suframa · 2008\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A Administração Pública de qualquer dos Poderes Nacionais obedecerá aos princípios de legalidade,\\nimpessoalidade, moralidade, publicidade e eficiência. O Código de Ética Profissional do Servidor\\nPúblico considera consolidada a moralidade quando há\",\"c\":\"A ideia da consolidação da moralidade aparece no texto do inciso III, na Seção Regras Deontológicas.\\n\\nIII - A moralidade da Administração Pública não se limita à distinção entre o bem e o mal, devendo ser acrescida da ideia de que o fim é sempre o bem comum. O equilíbrio entre a legalidade e a finalidade, na conduta do servidor público, é que poderá consolidar a moralidade do ato administrativo.\",\"o\":[\"cortesia, boa vontade, cuidado e tempo dedicado pelo agente público ao serviço público.\",\"equilíbrio entre a legalidade e a finalidade, na conduta do agente público. Aula 15 - Legislação\",\"assiduidade e pontualidade do servidor ao seu local de trabalho.\",\"rapidez, perfeição e rendimento no exercício de suas atribuições.\",\"obediência aos prazos de prestação de contas, condição essencial na gestão da coisa pública.\"],\"g\":1},{\"_id\":35,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Funrio MDIC · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim terá que\\ndecidir principalmente entre\",\"c\":\"Esse tema já foi cobrado em diversos concursos anteriores. A resposta para a nossa questão é dada pelo texto do inciso II das regras deontológicas.\\n\\nII - O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim, não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto, consoante as regras contidas no art. 37, caput, e § 4°, da Constituição Federal.\",\"o\":[\"o oportuno e o inoportuno.\",\"o conveniente e o inconveniente.\",\"o justo e o injusto.\",\"o ilegal e o legal.\",\"o honesto e o desonesto. Aula 15 - Legislação\"],\"g\":4},{\"_id\":36,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Funrio MDIC · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A publicidade de qualquer ato administrativo constitui requisito de eficácia e moralidade impondo sua\\nomissão comprometimento ético contra o bem comum, imputável a quem a negar, salvo somente nos\\ncasos de\",\"c\":\"A publicidade é a regra. O sigilo é a exceção. A questão nos exige o conhecimento do teor do inciso VII das regras deontológicas.\\n\\nVII - Salvo os casos de segurança nacional, investigações policiais ou interesse superior do Estado e da Administração Pública, a serem preservados em processo previamente declarado sigiloso, nos termos da lei, a publicidade de qualquer ato administrativo constitui requisito de eficácia e moralidade, ensejando sua omissão comprometimento ético contra o bem comum, imputável a quem a negar.\",\"o\":[\"segurança nacional e investigações policiais, a serem preservados em processo previamente declarado sigiloso, nos termos da lei.\",\"segurança nacional ou interesse do Estado ou da Administração Pública, a serem preservados em processo previamente declarado sigiloso, nos termos da lei.\",\"investigações policiais ou interesse do Estado ou da Administração Pública, a serem preservados em processo previamente declarado sigiloso, nos termos da lei.\",\"segurança nacional, investigações policiais ou interesse do Estado ou da Administração Pública, a serem preservados em processo previamente declarado sigiloso, nos termos da lei.\",\"epidemia, segurança nacional ou interesse do Estado ou da Administração Pública, a serem preservados em processo previamente declarado sigiloso, nos termos da lei.\"],\"g\":3},{\"_id\":37,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Funrio MDIC · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"À Comissão de Ética, criada nos termos do Decreto no. 1171, de 22/11/94, compete conhecer\\nconcretamente de imputação ou de procedimento susceptível de\",\"c\":\"A Comissão de Ética não é corregedoria. Ela não conduz Processo Administrativo Disciplinar, e nem aplica as penalidades previstas na Lei nº 8.112/1990. Pelo contrário, a pena aplicável pela comissão de ética é a censura.\",\"o\":[\"suspensão. Aula 15 - Legislação\",\"demissão.\",\"censura.\",\"censura e suspensão.\",\"demissão e suspensão.\"],\"g\":2},{\"_id\":38,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Anvisa · 2007\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Por meio do exercício dos princípios e valores morais no trabalho, como ser probo, reto, leal e justo,\\nentre outros, o servidor, além de desenvolver suas capacidades, habilidades e competências, projeta\\ntambém seus valores éticos.\",\"c\":\"Um dos deveres fundamentais do servidor público do Poder Executivo Federal é ser probo, reto, leal e justo, escolhendo sempre a opção que seja melhor para o bem comum, conforme o inciso XIV, alínea c, do Código de Ética.\",\"g\":\"C\"},{\"_id\":39,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Anvisa · 2007\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O servidor público jamais pode desprezar o elemento ético de sua conduta, embora, em algumas\\nsituações, tenha de decidir entre o que é legal e ilegal.\",\"c\":\"Logo no início do Código de Ética, na seção Regras Deontológicas, você pode observar no inciso II a importância que é dada ao elemento ético da conduta do servidor público. Além de decidir sobre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, caberá ao servidor decidir principalmente entre o honesto e o desonesto, conforme as regras que vimos no art. 37, §4º da Constituição Federal.\",\"g\":\"C\"},{\"_id\":40,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"FBN · 2013\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No exercício da função pública, segundo o Código de Ética do Servidor Público Federal, é vedado:\\n\\nAula 15 - Legislação\",\"c\":\"A única alternativa que trata diretamente de uma das vedações constantes no inciso XV é a que menciona a conivência com infrações ao Código de Ética. Perceba que o fato de alternativa mencionar os preceitos deontológicos não a torna errada, pois todo o Código de Ética deve ser observado pelos servidores públicos.\",\"o\":[\"liberar a prestação de contas, condição essencial da gestão dos bens, direitos e serviços da coletividade a seu cargo.\",\"denunciar pressões de superiores hierárquicos interessados em obter vantagens indevidas em decorrência de ações ilegais ou aéticas.\",\"ser frequente ao serviço, mesmo adoentado, para que não provoque danos ao trabalho ordenado, o que se reflete em todo o sistema.\",\"ser conivente, em razão do seu espírito de solidariedade, com infrações aos preceitos deontológicos.\"],\"g\":3},{\"_id\":41,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Ibama · 2012\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Uma psicóloga, funcionária concursada e contratada em um órgão público, que, após atender uma\\nservidora do órgão, sugerir que essa servidora faça acompanhamento terapêutico em seu consultório\\nparticular, por achar que atender nas dependências do órgão é impróprio, estará agindo de maneira\\nética, já que se prontifica a ajudar a servidora.\",\"c\":\"Achei esta questão bem interessante. Para mim fica bem claro que a conduta da servidora não está de acordo com a ética do serviço público. Além disso, acredito que a conduta pode ser enquadrada na proibição prevista no inciso XV, alínea g, pois ela está utilizando sua posição como servidora para obter vantagem pessoal.\",\"g\":\"E\"},{\"_id\":42,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Cesgranrio Finep · 2011\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Dentre as regras deontológicas do Código de Ética Profissional do Servidor Público Civil do Poder\\nExecutivo Federal, destaca-se o(a)\",\"c\":\"Aqui está o exemplo de uma questão bem elaborada sobre o Código de Ética.\\n\\nDe acordo com a alternativa A, o servidor seria obrigado a dar publicidade a todo e qualquer ato administrativo, mas você sabe que existem atos e documentos classificados como sigilosos, e existem leis específicas que tratam das hipóteses em que a publicidade pode ser restringida.\\n\\nA alternativa B é a nossa resposta. O cidadão deve ser sempre tratado com cortesia, e em diversas passagens o Código de Ética trata da possibilidade de o cidadão que é mal atendido sofrer dano moral.\\n\\nO erro da alternativa C está na separação estrita entre a vida privada e o conceito do servidor público em sua vida funcional. Vimos que o Código de Ética diz que a vida privada e a vida funcional caminham juntas, sendo possível que a conduta privada do servidor influencie em seu conceito profissional.\\n\\nNa alternativa D menciona-se a existência de valores éticos individuais. Esses valores existem, mas a conduta do servidor público deve ser pautada pelo Código de Ética e pelo bem comum, e não apenas por seus próprios valores.\\n\\nO erro na alternativa E está em dizer que o servidor pode falsear a verdade, quando esta for contrária aos interesses da Administração Pública ou da pessoa interessada. Na realidade o servidor deve sempre falar a verdade, “doa a quem doer”.\",\"o\":[\"dever de garantir a publicidade de todo e qualquer ato administrativo, ensejando sua omissão comprometimento ético contra o bem comum.\",\"dever de exercer suas funções com cortesia e boa vontade, sob pena de causar dano moral ao cidadão maltratado.\",\"dever de exercer sua função pública com zelo e dignidade, sendo sua vida privada independente do seu bom conceito na vida funcional.\",\"obrigação de decidir não apenas entre o legal e o ilegal, mas entre o honesto e o desonesto, consoante os valores éticos que cada indivíduo possui. Aula 15 - Legislação\",\"obrigação de dizer a verdade, salvo quando contrária aos interesses da pessoa interessada ou da Administração Pública.\"],\"g\":1},{\"_id\":43,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Cesgranrio Finep · 2011\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Pedro é contratado temporariamente por uma Sociedade de Economia Mista para fazer a manutenção\\ndas máquinas copiadoras. Pedro é responsável pela troca de peças e consertos em geral.\\n\\nFrequentemente, Pedro substitui peças com defeito por peças usadas em boas condições e as fatura\\npelo preço de peças novas. Para fins de apuração do comprometimento ético, a conduta de Pedro é\",\"c\":\"O Código de Ética, em seu inciso XXIV, determina que, para fins de apuração do comprometimento ético, o conceito de servidor público deve ser considerado na acepção mais ampla possível. Recomendo que você releia este inciso algumas vezes, e por isso resolvi reproduzi-lo aqui.\\n\\nXXIV - Para fins de apuração do comprometimento ético, entende-se por servidor público todo aquele que, por força de lei, contrato ou de qualquer ato jurídico, preste serviços de natureza permanente, temporária ou excepcional, ainda que sem retribuição financeira, desde que ligado direta ou indiretamente a qualquer órgão do poder estatal, como as autarquias, as fundações públicas, as entidades paraestatais, as empresas públicas e as sociedades de economia mista, ou em qualquer setor onde prevaleça o interesse do Estado.\\n\\nPerceba que a situação trazida pela questão envolve uma pessoa que presta serviços temporariamente a uma entidade estatal (sociedade de economia mista). Para fins de aplicação do Código de Ética, portanto, esta pessoa é considerada servidor público.\",\"o\":[\"indiferente, visto que o Código de Ética do Servidor Público aplica-se apenas àqueles devidamente contratados que prestem serviço de natureza permanente a qualquer órgão do poder estatal.\",\"indiferente, porque a Sociedade de Economia Mista prevê contratos sem comprovação de valor.\",\"indiferente, porque o contrato entre Pedro e a Sociedade de Economia Mista não veda esse tipo de comportamento.\",\"aética, visto que Pedro é equiparado a um servidor público para fins de apuração do comprometimento ético.\",\"aética, mas não passível de apuração, visto que Pedro presta serviços temporários a uma Sociedade de Economia Mista, onde não se aplica o Código de Ética do servidor público. Aula 15 - Legislação\"],\"g\":3},{\"_id\":44,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Cesgranrio Finep · 2011\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"São deveres fundamentais do Servidor Público Civil do Poder Executivo Federal, EXCETO\",\"c\":\"Entre as condutas apresentadas nas alternativas como deveres do servidor público, a única que soa um pouco estranha é a utilização do bom-senso para denunciar a prática de condutas aéticas ou contrárias ao interesse público, não é mesmo? Digo que soa estranho porque a forma como a alternativa foi escrita sugere que o servidor tem algum grau de liberdade para decidir se denunciará ou não a conduta inadequada, e isto não é verdade.\",\"o\":[\"ser probo, reto, leal e justo, sempre escolhendo a opção mais vantajosa para o bem comum.\",\"zelar, no exercício do direito de greve, pelas exigências específicas da defesa da vida e da segurança coletiva.\",\"resistir a todas as pressões de superiores hierárquicos que visem a obter favores ou vantagens indevidas, mesmo quando parecerem mais vantajosas para o bem comum.\",\"utilizar o seu bom-senso para comunicar a seus superiores os casos de condutas aéticas ou contrárias ao interesse público.\",\"desempenhar, a tempo, as atribuições do cargo, função ou emprego público de que seja titular.\"],\"g\":3},{\"_id\":45,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"Copeve UFAL · 2011\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Segundo as normas do Código de Ética dos Servidores Públicos Civis Federais, indique a opção que não\\nrepresenta uma vedação expressa aos referidos agentes públicos.\\n\\nAula 15 - Legislação\",\"c\":\"Recomendo que você leia novamente as alternativas. Perceba que o que torna a alternativa D incorreta é apenas a falta da letra “i”, que fez com que as ações imorais se tornassem ações morais. Além disso a alternativa traz um dever do servidor público e não uma vedação expressa no código de ética.\\n\\nEu sei que não é o tipo de questão ideal, mas preste bastante atenção, pois as questões da sua prova podem vir desse jeito.\",\"o\":[\"Usar de artifícios para procrastinar ou dificultar o exercício regular de direito por qualquer pessoa, causando-lhe dano moral ou material.\",\"Deixar de utilizar os avanços técnicos e científicos ao seu alcance ou do seu conhecimento para atendimento do seu mister.\",\"Exercer atividade profissional aética ou ligar o seu nome a empreendimentos de cunho duvidoso.\",\"Resistir a todas as pressões de superiores hierárquicos, de contratantes, interessados e outros que visem obter quaisquer favores, benesses ou vantagens indevidas em decorrência de ações morais, ilegais ou aéticas e denunciá-las.\",\"Prejudicar deliberadamente a reputação de outros servidores ou de cidadãos que deles dependam.\"],\"g\":3},{\"_id\":46,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"UFBA UFBA · 2006\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O Código de Ética Profissional do Servidor Público estabelece a dignidade, o decoro, o zelo, a eficácia,\\na consciência dos princípios morais e o dever de honestidade como primados maiores que devem\\nnortear o servidor público.\",\"c\":\"É verdade. Perceba que alguns desses princípios são trazidos apenas pelo Código de Ética, enquanto outros estão expressos também no art. 37 da Constituição Federal.\",\"g\":\"C\"},{\"_id\":47,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MS · 2006\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A pena aplicável ao servidor público pela comissão de ética é a de censura e sua fundamentação\\nconstará do respectivo parecer, assinado por todos os seus integrantes, com ciência do faltoso.\",\"c\":\"Algo que precisa ficar muito claro para você é que a comissão de ética não aplica penalidades de advertência, suspensão, demissão e nem de multa. A penalidade aplicável é a censura ética, que fica registrada nos assentamentos funcionais do servidor e pode servir de subsídio para decisões futuras em procedimentos administrativos, como por exemplo a promoção.\\n\\nAula 15 - Legislação\",\"g\":\"C\"},{\"_id\":48,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"ABIN · 2008\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os fatos e atos verificados na conduta do dia-a-dia do servidor em sua vida privada poderão acrescer\\nou diminuir o seu bom conceito na vida funcional, podendo caracterizar, inclusive, violação ao Código\\nde Ética, o que será passível de censura.\",\"c\":\"Aqui tratamos de dois dispositivos distintos do Código de Ética, e que talvez sejam os mais cobrados em prova. Primeiramente, você já sabe que a conduta adotada pelo servidor em sua vida privada influencia o seu conceito na vida profissional, não sendo possível dissociar completamente a vida profissional da privada.\\n\\nPor último, você também já sabe que a censura é a penalidade que pode ser aplicada em razão da violação do Código de Ética.\",\"g\":\"C\"},{\"_id\":49,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"FCC AL · 2010\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Ética é o conjunto de regras e preceitos de ordem valorativa e moral de um indivíduo, de um grupo\\nsocial ou de uma sociedade. A respeito da ética, considere:\\n\\nI – A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores\\nque devem nortear o serviço público.\\n\\nII – O equilíbrio entre a legalidade e a finalidade, na conduta do servidor público, é que poderá\\nconsolidar a moralidade do ato administrativo.\\n\\nIII – A moralidade na Administração Pública se limita à distinção entre o bem e o mal, não devendo ser\\nacrescida da ideia de que o fim é sempre o bem comum.\\n\\nIV – A função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular\\nde cada servidor público.\\n\\nV – O trabalho desenvolvido pelo servidor público perante a comunidade não deve ser entendido como\\nacréscimo ao seu próprio bem-estar, embora, como cidadão, seja parte integrante da sociedade.\\n\\nEstá correto o que se afirma APENAS em:\",\"c\":\"Aula 15 - Legislação\\n\\nNa assertiva III o erro está em limitar a moralidade à distinção entre bem e mal. Vimos na aula de hoje que essa distinção vai muito além disso, chegando até à distinção entre o honesto e o desonesto. Além disso, a conduta do servidor público deve ser sempre orientada para o bem comum. O outro erro está na assertiva V, que diz que o trabalho do servidor não deve ser entendido como acréscimo ao seu próprio bem estar. Isso não faz muito sentido, já que o servido trabalha para o bem da sociedade, da qual ele mesmo também faz parte. As demais assertivas estão corretas.\",\"o\":[\"I, II e IV.\",\"I, III e IV.\",\"II, III e IV.\",\"II, IV e V.\",\"III, IV e V.\"],\"g\":0},{\"_id\":50,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"FCC DNOCS · 2010\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Com relação às Comissões de Ética dispostas no Código de Ética Profissional do Servidor Público Civil\\ndo Poder Executivo Federal, considere:\\n\\nI. Em todos os órgãos e entidades da Administração Pública Federal direta, indireta autárquica e\\nfundacional, ou em qualquer órgão ou entidade que exerça atribuições delegadas pelo poder público,\\ndeverá ser criada uma Comissão de Ética.\\n\\nII. Incumbe ao servidor fornecer seu registro da sua conduta ética para a Comissão de Ética,\\nencarregada da execução do quadro de carreira dos servidores, para o efeito de instruir e fundamentar\\npromoções e para todos os demais procedimentos próprios da carreira do servidor público.\\n\\nIII. A pena aplicável ao servidor público pela Comissão de Ética é a de censura e sua fundamentação\\nconstará do respectivo parecer, assinado por todos os seus integrantes, com ciência do faltoso.\\n\\nIV. Para fins de apuração do comprometimento ético, entende-se por servidor público, exclusivamente,\\na pessoa que, por força de lei, preste serviços de natureza permanente condicionada ao recebimento\\nde salário e esteja ligado direta ou indiretamente a qualquer órgão do poder estatal, como as\\nautarquias e as fundações públicas.\\n\\nEstá correto o que consta APENAS em\",\"c\":\"Temos aqui mais uma questão que aborda diversos aspectos do Código de Ética.\\n\\nA assertiva I está correta, pois todos os órgãos e entidades da Administração Pública Federal (com exceção das empresas públicas e sociedades de economia mista), bem como órgãos e entidades que exerça atribuições delegadas do Poder Público, devem criar comissões de ética, nos termos do Código.\\n\\nAula 15 - Legislação\\n\\nA assertiva II faz uma confusão, pois na realidade a comissão de ética é que tem a obrigação de fornecer os registros sobre a conduta ética de cada servidor aos órgãos responsáveis pela execução do quadro de carreira dos servidores.\\n\\nA assertiva III está estritamente de acordo com o inciso XXII do Código de Ética.\\n\\nA assertiva IV restringe o conceito de servidor público trazido pelo Código de Ética. Para fins de aplicação do Código, considera-se como servidor público “todo aquele que, por força de lei, contrato ou de qualquer ato jurídico, preste serviços de natureza permanente, temporária ou excepcional, ainda que sem retribuição financeira, desde que ligado direta ou indiretamente a qualquer órgão do poder estatal, como as autarquias e as fundações públicas, as entidades paraestatais, as empresas públicas e as sociedades de economia mista, ou em qualquer setor onde prevaleça o interesse do Estado”.\",\"o\":[\"I e III.\",\"I e II.\",\"II e III.\",\"II e IV.\",\"III e IV.\"],\"g\":0},{\"_id\":51,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"INSS · 2016\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Bruno, servidor contratado temporariamente para prestar serviços a determinado órgão público\\nfederal, praticou conduta vedada aos servidores públicos pelo Código de Ética Profissional do Servidor\\nPúblico Civil do Poder Executivo Federal.\\n\\nA partir dessa situação hipotética, julgue os itens a seguir à luz do disposto nos Decretos n.º 1.171/1994\\ne n.º 6.029/2007.\\n\\nSe, para a infração praticada por Bruno, estiverem previstas as penalidades de advertência ou\\nsuspensão, a comissão de ética será competente para, após o regular procedimento, aplicar\\ndiretamente a penalidade.\",\"c\":\"Você é aluno do Estratégia e sabe do fundo do seu coração que as comissões de ética apenas são competentes para aplicar uma punição, que é a censura ética. Punições de natureza disciplinar, como a advertência e suspensão, somente podem ser aplicadas por meio de sindicâncias ou processos administrativos disciplinares, que são conduzidos por outras comissões.\",\"g\":\"E\"},{\"_id\":52,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"INSS · 2016\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Bruno, servidor contratado temporariamente para prestar serviços a determinado órgão público\\nfederal, praticou conduta vedada aos servidores públicos pelo Código de Ética Profissional do Servidor\\nPúblico Civil do Poder Executivo Federal.\\n\\nA partir dessa situação hipotética, julgue os itens a seguir à luz do disposto nos Decretos n.º 1.171/1994\\ne n.º 6.029/2007.\\n\\nMesmo prestando serviço de natureza temporária, Bruno está sujeito às disposições contidas no\\nDecreto n.º 1.171/1994.\\n\\nAula 15 - Legislação\",\"c\":\"O Decreto nº 1.171/1994, que instituiu o Código de Ética do Servidor Público Civil do Poder Executivo Federal é aplicável a “todo aquele que, por força de lei, contrato ou de qualquer ato jurídico, preste serviços de natureza permanente, temporária ou excepcional, ainda que sem retribuição financeira, desde que ligado direta ou indiretamente a qualquer órgão do poder estatal, como as autarquias, as fundações públicas, as entidades paraestatais, as empresas públicas e as sociedades de economia mista, ou em qualquer setor onde prevaleça o interesse do Estado”. Podemos concluir, portanto, que o fato de Bruno ser servidor temporário não o exclui da aplicação do Código de Ética.\",\"g\":\"C\"},{\"_id\":53,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"INSS · 2016\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Embora deva respeitar a hierarquia, o servidor público está obrigado a representar contra ações\\nmanifestamente ilegais de seus superiores hierárquicos.\",\"c\":\"O dever de respeito à hierarquia encontra limitações, relacionadas justamente à possibilidade do cometimento de ilegalidades pelos superiores. Nesse caso o servidor tem o dever representar, conforme inciso XIV, “h” do Código de Ética.\",\"g\":\"C\"},{\"_id\":54,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"IFF · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com o Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal,\\npode caracterizar imprudência no desempenho da função pública o(a)\",\"c\":\"Está correto o item A, nos termos do inciso XI do Código de Ética:\\n\\nXI – O servidor deve prestar toda a sua atenção às ordens legais de seus superiores, velando atentamente por seu cumprimento, e, assim, evitando a conduta negligente. Os repetidos erros, o descaso e o acúmulo de desvios tornam-se, às vezes, difíceis de corrigir e caracterizam até mesmo imprudência no desempenho da função pública.\",\"o\":[\"repetição de erros.\",\"dano causado a qualquer bem pertencente ao patrimônio público.\",\"omissão da verdade.\",\"permissão de atraso na prestação do serviço.\",\"retardamento na prestação de contas.\"],\"g\":0},{\"_id\":55,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item seguinte, relativo ao regime dos servidores públicos federais e à ética no serviço público.\\n\\nComissões de ética são obrigatórias para todos os órgãos da administração pública federal direta,\\nsendo facultativas para entidades da administração indireta.\",\"c\":\"Errado! Conforme o inciso XVI do Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal (decreto n° 1.171/1994), “em todos os órgãos e entidades da Administração Pública Federal direta, indireta autárquica e fundacional, ou em qualquer órgão ou entidade que exerça atribuições delegadas pelo poder público, deverá ser criada uma Comissão de Ética.”\\n\\nReforçando o tema, o decreto n° 1.171/1994, ao aprovar o referido Código de Ética, ressaltou em seu art. 2º que:\\n\\nArt. 2º. Os órgãos e entidades da Administração Pública Federal direta e indireta implementarão, em sessenta dias, as providências necessárias à plena vigência do Código de Ética, inclusive mediante a Constituição da respectiva Comissão de Ética, integrada por três servidores ou empregados titulares de cargo efetivo ou emprego permanente.\\n\\nPerceba que a implementação das Comissões de Ética não é uma mera faculdade dos órgãos e entidades da Administração Pública, mas verdadeiro dever. É uma obrigação!\",\"g\":\"E\"},{\"_id\":56,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item seguinte, relativo ao regime dos servidores públicos federais e à ética no serviço público.\\n\\nÉ dever do servidor público facilitar a fiscalização de serviço público cuja prestação esteja sob sua\\nresponsabilidade.\",\"c\":\"Certo! Fixa o inciso XIV, alínea s, do Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal (decreto n° 1.171/1994), que um dos deveres fundamentais do servidor público é o de “facilitar a fiscalização de todos atos ou serviços por quem de direito.”\\n\\nEm verdade, nada mais óbvio que aquele que exerce um cargo ou função pública tenha o dever de facilitar a fiscalização do serviço público cuja prestação esteja sob sua responsabilidade. Afinal, todos os cargos, funções e serviços desta natureza devem sempre visar a concretização do bem comum, sendo a fiscalização um dos componentes essenciais para a sua correta realização.\",\"g\":\"C\"},{\"_id\":57,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Aula 15 - Legislação\\n\\nJulgue o seguinte item, a respeito da ética no serviço público.\\n\\nApesar de a função pública ser tida como exercício profissional, ela não se integra à vida particular do\\nindivíduo e, portanto, os atos praticados em sua vida privada não poderão acrescer ou diminuir o seu\\nconceito na vida funcional.\",\"c\":\"Errado! O inciso VI do decreto n° 1.171/1994 aponta exatamente o contrário. Deste modo:\\n\\nVI - A função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular de cada servidor público. Assim, os fatos e atos verificados na conduta do dia-a-dia em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\\n\\nAliás, sobre o tema convém destacar o inciso I do mesmo diploma legal, pelo qual:\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos.\",\"g\":\"E\"},{\"_id\":58,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o seguinte item, a respeito da ética no serviço público.\\n\\nA comissão de ética de um órgão, caso todos os seus integrantes estejam de acordo, pode aplicar penas\\nque vão desde a censura até a demissão de um servidor.\",\"c\":\"Errado! A comissão de ética de um órgão pode aplicar ao servidor somente a pena de censura, nunca a de demissão. Neste sentido, o inciso XXII do decreto n° 1.171/1994:\\n\\nXXII - A pena aplicável ao servidor público pela Comissão de Ética é a de censura e sua fundamentação constará do respectivo parecer, assinado por todos os seus integrantes, com ciência do faltoso.\\n\\nVale ressaltar, todavia, que nos termos do art. 12, §5º, inciso III, do decreto n° 6.029/2007, caso a Comissão de Ética de um órgão chegue à conclusão de que o servidor efetivamente cometeu falta ética, poderá recomendar a abertura de procedimento administrativo, e neste sim, desde que garantida a ampla defesa, poderá haver a demissão, como bem preceitua o art. 41, §1º, inciso II, da CF/1988.\\n\\nEm se tratando de cargo ou função de confiança, também poderá a Comissão encaminhar sugestão de exoneração à autoridade hierarquicamente superior ou ainda a devolução do servidor ao órgão de origem, a depender do caso. (Art. 12, §5º, inciso I, do decreto n° 6.029/2007)\",\"g\":\"E\"},{\"_id\":59,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o seguinte item, a respeito da ética no serviço público.\\n\\nO servidor que alegar desconhecimento de alguma norma de serviço ou legislação inerente ao órgão\\nem que atua contrariará os preceitos fundamentais de ética do setor público.\",\"c\":\"Certo! A concretização da ética no serviço público exige do servidor não apenas que atue com honestidade, mas também que no exercício de suas funções mantenha o zelo e a busca pela eficácia. Não por menos, entre os seus deveres fundamentais está o de manter-se atualizado com as instruções, as normas de serviço e a legislação pertinentes ao órgão onde exerce suas funções. (Inciso XIV, alínea q, do decreto n° 1.171/1994). Logo, contrariará os preceitos fundamentais de ética do setor público o servidor que alegar desconhecimento de alguma norma de serviço ou legislação que sejam inerentes ao órgão em que atua.\",\"g\":\"C\"},{\"_id\":60,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o seguinte item, a respeito da ética no serviço público.\\n\\nO uso do cargo ou função pública para obter favorecimento, desde que não haja prejuízo a outrem,\\nnão constitui afronta à ética e à moral do serviço público.\",\"c\":\"Errado! O cargo ou a função pública sempre deverão ser utilizados para a satisfação do bem comum, de modo que o servidor público jamais poderá desprezar o elemento ético de sua conduta com a intenção de satisfazer seus interesses pessoais. Não por menos, o decreto n° 1.171/1994 expressamente prevê em seu inciso XV que:\\n\\nXV - É vedado ao servidor público;\\n\\na) o uso do cargo ou função, facilidades, amizades, tempo, posição e influências, para obter\\n\\nqualquer favorecimento, para si ou para outrem;\",\"g\":\"E\"},{\"_id\":61,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"EBSERH · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o seguinte item, a respeito da ética no serviço público.\\n\\nA ausência injustificada de um servidor público ao seu local de trabalho constitui fator de\\ndesmoralização do serviço público.\",\"c\":\"Certo! Trata-se do teor literal do previsto no inciso XII do decreto n° 1.171/94:\\n\\nXII - Toda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço público, o que quase sempre conduz à desordem nas relações humanas.\\n\\nEm complemento, cito a alínea l do inciso XIV do aludido decreto, pelo qual é dever fundamental do servidor público:\\n\\nl) ser assíduo e frequente ao serviço, na certeza de que sua ausência provoca danos ao trabalho ordenado, refletindo negativamente em todo o sistema;\",\"g\":\"C\"},{\"_id\":62,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"STJ · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considerando os conceitos, princípios e valores da ética e da moral, bem como o disposto na Lei n.º\\n8.429/1992, julgue o item a seguir.\\n\\nA consciência moral deve nortear o comportamento do servidor público, que deve sempre apresentar\\nconduta ética, ainda que receba ordem hierárquica superior que lhe imponha conduta imoral e\\nantiética.\",\"c\":\"Certo! Não há dúvidas de que o respeito a hierarquia está entre os deveres fundamentais do servidor público no exercício de seu cargo ou função. Todavia, mais importante do que obedecer aos seus superiores é obedecer àquilo que é determinado pela lei e, principalmente, pelos princípios morais e éticos. Exatamente por isso, também é dever do servidor representar, sem nenhum temor, contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal (inciso XIV, alínea h, do decreto n° 1.171/94), assim como resistir a todas as pressões de superiores hierárquicos que visem obter quaisquer favores, benesses ou vantagens indevidas em decorrência de ações imorais, ilegais ou aéticas e denunciá-las (inciso XIV, alínea i, do decreto n° 1.171/94), devendo, ainda, comunicar imediatamente a seus superiores todo e qualquer ato ou fato contrário ao interesse público, exigindo as providências cabíveis (inciso XIV, alínea m, do decreto n° 1.171/94).\\n\\nLembre-se que nos termos do inciso II do decreto n° 1.171/94:\\n\\nII - O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim, não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto, consoante as regras contidas no art. 37, caput, e § 4°, da Constituição Federal.\\n\\nAula 15 - Legislação\",\"g\":\"C\"},{\"_id\":63,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"PC · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Julgue o item que se segue, a respeito das atitudes do servidor público no desempenho das suas\\nfunções.\\n\\nI O fato de um servidor público deixar qualquer pessoa à espera de solução que compete ao setor em\\nque ele exerça suas funções, acarretando atraso na prestação do serviço, caracteriza atitude contra a\\nética, mas não grave dano moral ao usuário dos serviços públicos.\\n\\nII Tratar mal uma pessoa que paga seus próprios tributos significa, direta ou indiretamente, causar-lhe\\ndano moral.\\n\\nIII Os repetidos erros, o descaso e o acúmulo de desvios por parte do servidor público tornam-se, às\\nvezes, difíceis de corrigir e podem caracterizar negligência no desempenho da função pública, mas não\\nimprudência.\\n\\nIV Toda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço\\npúblico.\\n\\nEstão certos apenas os itens\",\"c\":\"O gabarito é o item C (estão certos apenas os itens II e IV)\\n\\nItem I: errado! O fato de um servidor público deixar qualquer pessoa à espera de solução que compete ao setor em que ele exerça suas funções, acarretando atraso na prestação do serviço, caracteriza atitude contra a ética e também grave dano moral ao usuário dos serviços públicos.\\n\\nNeste sentido, o inciso X do decreto n° 1.171/1994:\\n\\nX - Deixar o servidor público qualquer pessoa à espera de solução que compete ao setor em que exerça suas funções, permitindo a formação de longas filas, ou qualquer outra espécie de atraso na prestação do serviço, não caracteriza apenas atitude contra a ética ou ato de desumanidade, mas principalmente grave dano moral aos usuários dos serviços públicos.\\n\\nItem II: correto! É o que está previsto no inciso IX do decreto n° 1.171/1994. Veja:\\n\\nIX - A cortesia, a boa vontade, o cuidado e o tempo dedicados ao serviço público caracterizam o esforço pela disciplina. Tratar mal uma pessoa que paga seus tributos direta ou indiretamente significa causar-lhe dano moral. Da mesma forma, causar dano a qualquer bem\\n\\nAula 15 - Legislação\\n\\npertencente ao patrimônio público, deteriorando-o, por descuido ou má vontade, não constitui apenas uma ofensa ao equipamento e às instalações ou ao Estado, mas a todos os homens de boa vontade que dedicaram sua inteligência, seu tempo, suas esperanças e seus esforços para construí- los.\\n\\nItem III: errado! Os repetidos erros, o descaso e o acúmulo de desvios por parte do servidor público tornam- se, às vezes, difíceis de corrigir e podem caracterizar imprudência no desempenho da função pública, mas não negligência.\\n\\nLeia com atenção a redação do Inciso XI do decreto n° 1.171/1994:\\n\\nXI - O servidor deve prestar toda a sua atenção às ordens legais de seus superiores, velando atentamente por seu cumprimento, e, assim, evitando a conduta negligente. Os repetidos erros, o descaso e o acúmulo de desvios tornam-se, às vezes, difíceis de corrigir e caracterizam até mesmo imprudência no desempenho da função pública.\\n\\nItem IV: correto! De fato, conforme o inciso XII do decreto n° 1.171/1994, “toda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço público, o que quase sempre conduz à desordem nas relações humanas.”\",\"o\":[\"I e II.\",\"I e III.\",\"II e IV.\",\"I, III e IV.\",\"II, III e IV.\"],\"g\":2},{\"_id\":64,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"TRE · 2017\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Acerca da ética no serviço público, assinale a opção correta.\",\"c\":\"Está correto o item E.\\n\\nLetra E: correta! O decreto n° 1.171/1994 definiu de maneira bastante ampla o conceito de servidor público para os fins de apuração do comprometimento ético. Leia com atenção o inciso XXIV:\\n\\nXXIV - Para fins de apuração do comprometimento ético, entende-se por servidor público todo aquele que, por força de lei, contrato ou de qualquer ato jurídico, preste serviços de natureza\\n\\nAula 15 - Legislação\\n\\npermanente, temporária ou excepcional, ainda que sem retribuição financeira, desde que ligado direta ou indiretamente a qualquer órgão do poder estatal, como as autarquias, as fundações públicas, as entidades paraestatais, as empresas públicas e as sociedades de economia mista, ou em qualquer setor onde prevaleça o interesse do Estado.\\n\\nSendo assim, é correto afirmar que tanto os termos de compromisso dos estagiários como os contratos administrativos de prestação de serviço firmados com o TRE/PE devem observar as normas de natureza ética desse tribunal, pois ambos correspondem a servidores públicos que por força de contrato ou qualquer outro ato jurídico prestam serviços de natureza temporária e que estão diretamente ligados a órgão do Poder Estatal.\\n\\nLetra A: errada! Os servidores do TRE/PE podem estabelecer livre interlocução com seus superiores, podendo expor ideias e opiniões, ainda que seja para discutir aspecto controverso em instrução processual.\\n\\nÉ dever do servidor público respeitar a hierarquia e atender as ordens legais de seus superiores, contudo, também é sua obrigação questionar temas controversos que possam trazer prejuízos aos princípios éticos que regem a conduta estatal, seja no curso da instrução processual ou não.\\n\\nComo bem esclarece o inciso XIV, alínea h, do decreto n° 1.174/1994:\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nh) ter respeito à hierarquia, porém sem nenhum temor de representar contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal;\\n\\nLetra B: errada! Isto porque, exige-se sim que haja harmonia entre os valores institucionais e as práticas pessoais do servidor público. Não é por menos que o decreto n° 1.174/1994 estabelece que o servidor deve observância aos princípios morais tanto no exercício do cargo ou função quanto fora dele, em sua vida particular.\\n\\nNeste sentido, os inciso I e VI do decreto n° 1.171/1994:\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos VI - A função pública deve ser tida como exercício profissional e, portanto, se integra na vida particular de cada servidor público. Assim, os fatos e atos verificados na conduta do dia-a-dia em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\\n\\nLetra C: errada! Não seria razoável admitir que servidor do TRE/PE pudesse prestar consultoria técnica a empresas licitantes ou que prestem serviços a esse tribunal, independentemente de estarem envolvidas ou não com o processo eleitoral. Conforme o inciso XV, alínea a, do decreto n° 1.171/1994, é vedado ao servidor o uso do cargo ou função para obter qualquer favorecimento, para si ou para outrem.\\n\\nPerceba que admitir tal hipótese geraria inaceitável conflito de interesses, pois de um lado teríamos o TRE, órgão do Poder Judiciário responsável pelo gerenciamento das eleições e que para bem cumprir sua\\n\\nAula 15 - Legislação\\n\\nfinalidade celebra uma série de contratos com fornecedores de bens e prestadores de serviços, sempre visando a satisfação do interesse público. De outro lado, haveria uma empresa que atua precipuamente com o fim de obter lucro, visando satisfazer não o bem o comum, mas apenas os interesses particulares de seus gestores, e entre estas duas instituições existiria um servidor público que poderia ter acesso a informações privilegiadas pela posição que ocupa no tribunal e repassá-las a empresa, favorecendo-a nos procedimentos licitatórios em detrimento dos demais concorrentes e dos princípios da moralidade, da igualdade e da eficiência.\\n\\nOs servidores públicos no exercício de suas atividades devem atuar com dignidade, decoro e zelo pela função pública, evitando qualquer medida que possa comprometer ou fundar a suspeita de imoralidades.\\n\\nLetra D: errada! Como já foi explicado no item E, o decreto n° 1.171/1994 adotou um conceito bastante amplo para definir servidor público. Assim, os princípios e normas de conduta ética são aplicáveis aos servidores efetivos e também aos que mesmo pertencendo a outra instituição, prestem serviços ao TRE/PE, ainda que desenvolvam atividade de natureza permanente, temporária ou excepcional.\",\"o\":[\"Os servidores do TRE/PE podem estabelecer livre interlocução com seus superiores, podendo expor ideias e opiniões, desde que não seja para discutir aspecto controverso em instrução processual.\",\"Os atos, comportamentos e atitudes dos servidores terão de incluir, sempre, uma avaliação de natureza ética, embora não se exija uma harmonia entre os valores institucionais e as práticas pessoais.\",\"O servidor do TRE/PE pode prestar consultoria técnica a empresas licitantes ou que prestem serviços a esse tribunal, desde que elas não estejam envolvidas com o processo eleitoral.\",\"Os princípios e normas de conduta ética são aplicáveis aos servidores efetivos e aos que, mesmo pertencendo a outra instituição, prestem serviços ao TRE/PE, desde que desenvolvam atividade de natureza permanente.\",\"Tanto os termos de compromisso dos estagiários como os contratos administrativos de prestação de serviço firmados com o TRE/PE devem observar as normas de natureza ética desse tribunal.\"],\"g\":4},{\"_id\":65,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"SEDF · 2017\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"À luz da legislação que rege os atos administrativos, a requisição dos servidores distritais e a ética no\\nserviço público, julgue o seguinte item.\\n\\nServidor público do DF apresentar-se ao trabalho com vestimentas inadequadas ao exercício do cargo\\nnão constitui vedação relativa a comportamento profissional e atitudes éticas no serviço.\",\"c\":\"Errado! Entre os deveres fundamentais do servidor público está o de apresentar-se ao trabalho com vestimentas adequadas ao exercício da função. (Inciso XIV, alínea p, decreto n° 1.171/94)\",\"g\":\"E\"},{\"_id\":66,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"PC · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Do ponto de vista atitudinal, o servidor público, no desempenho das suas atribuições,\",\"c\":\"Está correto o item D. Segundo a alínea m, do inciso XIV, do decreto n° 1.171/1994, é dever fundamental do servidor público “comunicar imediatamente a seus superiores todo e qualquer ato ou fato contrário ao interesse público, exigindo as providências cabíveis”.\\n\\nLetra A: errada! Realmente, o servidor público deve respeitar a hierarquia, contudo, é seu dever representar, sem nenhum temor, contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal. (Inciso XIV, alínea h, do decreto n° 1.171/1994)\\n\\nLetra B: errada! O erro está logo no começo da assertiva, pois determina o inciso XIV, alínea t, do decreto n° 1.171/1994, que é dever fundamental do servidor “exercer com estrita moderação as prerrogativas funcionais que lhe sejam atribuídas, abstendo-se de fazê-lo contrariamente aos legítimos interesses dos usuários do serviço público e dos jurisdicionados administrativos”.\\n\\nPortanto, no exercício do cargo ou função pública, cabe ao servidor se ater aos precisos termos da lei e dos princípios éticos, não podendo atuar de acordo com a sua própria faculdade, ou seja, com aquilo que quer fazer de acordo apenas com as suas vontades e com o que julga adequado.\\n\\nLetra C: errada! Além do que acabamos de ver na assertiva acima, estabelece o inciso XIV, alínea u, do decreto n° 1.171/1994, que:\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\n[...]\\n\\nu) abster-se, de forma absoluta, de exercer sua função, poder ou autoridade com finalidade estranha ao interesse público, mesmo que observando as formalidades legais e não cometendo qualquer violação expressa à lei;\\n\\nLetra E: errada! Quando estiver diante de duas opções, o servidor público sempre deverá escolher a melhor e a mais vantajosa para o bem comum. Olha o que o inciso XIV, alínea c, do decreto n° 1.171/1994 determina:\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\nc) ser probo, reto, leal e justo, demonstrando toda a integridade do seu caráter, escolhendo\\n\\nsempre, quando estiver diante de duas opções, a melhor e a mais vantajosa para o bem comum;\",\"o\":[\"deve respeitar a hierarquia, tomando cuidado ao representar contra determinados comprometimentos indevidos da estrutura em que se funda o poder estatal.\",\"poderá, usando a própria faculdade, exercer as prerrogativas funcionais que lhe sejam atribuídas, desde que sua atuação tenha foco no objetivo no bem comum.\",\"poderá exercer sua função com finalidade estranha ao interesse público, desde que sua atuação satisfaça interesse legítimo do destinatário da prestação de serviço.\",\"deve comunicar imediatamente a seus superiores todo e qualquer ato contrário ao interesse público e exigir as providências cabíveis. Aula 15 - Legislação\",\"deve escolher sempre, quando estiver diante de duas opções, a melhor e a mais vantajosa para a administração pública.\"],\"g\":3},{\"_id\":67,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"UFRRJ UFRRJ · 2015\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Um funcionário que presta serviços a um órgão público federal por meio de uma empresa terceirizada,\\nhabitualmente é encontrado embriagado após o horário de expediente, fato que lhe rendeu, inclusive,\\nproblemas de relacionamento com os moradores próximos ao órgão público. Diante desse contexto,\\ntal funcionário,\",\"c\":\"A embriaguez habitual é vedada no serviço ou fora dele, nos termos do inciso XV, “n”.\\n\\nXV - E vedado ao servidor público;\\n\\nn) apresentar-se embriagado no serviço ou fora dele habitualmente;\\n\\nOutro ponto importante que deve ser mencionado aqui é que o Código de Ética se aplica a servidores públicos considerados de forma bastante ampla, alcançando inclusive estagiários e colaboradores terceirizados.\\n\\nPor fim, como você já está cansado e saber, a única penalidade que pode ser aplicada em caso descumprimento do Código de Ética é a censura.\",\"o\":[\"estará isento de sofrer qualquer penalidade administrativa, pois não possui vínculo direto com o órgão público onde presta serviços.\",\"será advertido por escrito, caso seja provada, por comissão de sindicância, sua embriaguez habitual.\",\"terá sua suspensão recomendada pela comissão de ética por até 15 (quinze) dias, caso seja comprovada sua embriaguez habitual.\",\"poderia receber qualquer tipo de penalidade somente caso se encontrasse embriagado no horário de expediente.\",\"receberia a pena de censura por meio da comissão de ética em sendo comprovada a embriaguez habitual.\"],\"g\":4},{\"_id\":68,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"UFRRJ UFRRJ · 2015\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Segundo o Código de Ética do Servidor Público, existem primados que norteiam as atividades da\\ncategoria. Os princípios contidos nesta normativa são:\",\"c\":\"Os primados maiores que devem nortear a conduta do servidor público constam no inciso I das regras deontológicas. Vamos relembrar?!\\n\\nI - A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal. Seus atos, comportamentos e atitudes serão direcionados para a preservação da honra e da tradição dos serviços públicos.\",\"o\":[\"dignidade, decoro, zelo e consciência dos princípios morais.\",\"decoro, moralidade, efetividade e consciência dos princípios morais.\",\"zelo, legalidade, eficiência e decoro.\",\"dignidade, efetividade, impessoalidade e consciência dos princípios morais.\",\"dignidade, decoro, zelo, eficiência e publicidade. Aula 15 - Legislação\"],\"g\":0},{\"_id\":69,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"UFRRJ UFRRJ · 2015\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O Código de Ética Profissional do Servidor Público Civil do Poder Executivo foi instituído pelo Decreto\\nnº 1.171/94. Considerando esse decreto, assinale a alternativa que corresponde a uma vedação ao\\nservidor público.\",\"c\":\"Mais uma vez a banca examinadora elabora uma questão que poderia ser respondida com um pouco de bom senso. Parece bobo, mas são muito comuns as questões que pedem para marcar uma proibição e apresentam várias alternativas com deveres. Basta prestar um pouco de atenção para perceber que apenas a alternativa A traz uma conduta proibida, não é mesmo!?\\n\\nXV - E vedado ao servidor público;\\n\\np) exercer atividade profissional aética ou ligar o seu nome a empreendimentos de cunho duvidoso.\",\"o\":[\"Exercer atividade profissional aética ou ligar o seu nome a empreendimentos de cunho duvidoso.\",\"Facilitar a fiscalização de todos os atos e serviços por quem de direito.\",\"Jamais retardar qualquer prestação de contas, condição essencial da gestão dos bens, direitos e serviços da coletividade a seu cargo.\",\"Manter-se atualizado com as instruções, as normas de serviço e a legislação pertinentes ao órgão onde exerce suas funções.\",\"Apresentar-se ao trabalho com vestimentas adequadas ao exercício da função.\"],\"g\":0},{\"_id\":70,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"UFRRJ UFRRJ · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Leia as afirmativas abaixo, considerando as vedações imputadas ao servidor público, segundo o\\nDecreto 1.171, de 22/06/1994.\\n\\nI. Usar de artifícios para procrastinar ou dificultar o exercício regular de direito por qualquer pessoa,\\ncausando-lhe dano moral ou material.\\n\\nII. Desviar servidor público para atendimento a interesse particular.\\n\\nAula 15 - Legislação\\n\\nIII. Retirar da repartição pública, estando legalmente autorizado, qualquer documento, livro ou bem\\npertencente ao patrimônio público.\\n\\nIV. Apresentar-se embriagado no serviço ou fora dele habitualmente.\\n\\nV. Utilizar os avanços técnicos e científicos ao seu alcance ou do seu conhecimento para atendimento\\ndo seu mister.\\n\\nDas afirmativas acima, estão corretas somente\",\"c\":\"Apenas os itens I, II e IV realmente se referem a vedações previstas no Código de Ética.\\n\\nQuanto ao item III, existe a vedação de retirar da repartição pública bens e documentos quando não há autorização. Se o servidor estiver autorizado, portanto, não há nenhuma violação.\\n\\nO item V, por sua vez, está menciona a vedação à utilização dos avanços técnicos e científicos, mas na realidade a vedação incide sobre a não utilização desses avanços.\",\"o\":[\"I, II e IV.\",\"I e IV.\",\"II, III e IV.\",\"II e IV.\",\"I, II e III.\"],\"g\":0},{\"_id\":71,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"UFRRJ UFRRJ · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O Código de Ética do Servidor Público (Decreto n° 1.171/94) estabelece como dever fundamental do\\nservidor\",\"c\":\"Aula 15 - Legislação\\n\\nA alternativa A está incorreta. Nos termos do inciso IV, “a”, o servidor tem o dever de desempenhar, a tempo, as atribuições do cargo, função ou emprego público de que seja titular.\\n\\nA alternativa B está incorreta. O servidor tem o dever de manter-se atualizado com as instruções, as normas de serviço e a legislação pertinentes ao órgão onde exerce suas funções (inciso XIV, “q”).\\n\\nA alternativa C está correta e é a nossa resposta. O servidor tem o dever de participar dos movimentos e estudos que se relacionem com a melhoria do exercício de suas funções, tendo por escopo a realização do bem comum (inciso XIV, “o”).\\n\\nA alternativa D está incorreta. Nos termos do inciso XIV, “h”, o servidor deve ter respeito à hierarquia, porém sem nenhum temor de representar contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal.\\n\\nA alternativa E está incorreta. É dever do servidor exercer suas atribuições com rapidez, perfeição e rendimento, pondo fim ou procurando prioritariamente resolver situações procrastinatórias, principalmente diante de filas ou de qualquer outra espécie de atraso na prestação dos serviços pelo setor em que exerça suas atribuições, com o fim de evitar dano moral ao usuário (inciso XIV, “b”).\",\"o\":[\"desempenhar, com estrita moderação, as atribuições do cargo, função ou emprego público de que seja titular.\",\"realizar, periodicamente, cursos de atualização para atender ao princípio constitucional da eficiência\",\"participar dos movimentos e estudos que se relacionem com a melhoria do exercício de suas funções, tendo por escopo a realização do bem comum.\",\"respeitar a hierarquia com temor de representar contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal.\",\"exercer suas atribuições com rapidez, perfeição e rendimento, procurando ensejar situações procrastinatórias.\"],\"g\":2},{\"_id\":72,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2019\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com o Código de Ética Profissional, o servidor público civil do Poder Executivo Federal deverá\",\"c\":\"A alternativa A está incorreta. A regra da publicidade encontra exceções, a exemplo dos casos de segurança nacional e interesse superior do Estado e da Administração Pública.\\n\\nVII - Salvo os casos de segurança nacional, investigações policiais ou interesse superior do Estado e da Administração Pública, a serem preservados em processo previamente declarado sigiloso, nos termos da lei, a publicidade de qualquer ato administrativo constitui requisito de eficácia e moralidade, ensejando sua omissão comprometimento ético contra o bem comum, imputável a quem a negar.\\n\\nA alternativa B está incorreta. As normas do Código de Ética devem ser divulgadas a todos.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\nAula 15 - Legislação\\n\\nv) divulgar e informar a todos os integrantes da sua classe sobre a existência deste Código de Ética, estimulando o seu integral cumprimento.\\n\\nA alternativa C está incorreta. O servidor tem o dever de facilitar a fiscalização de todos os atos ou serviços por quem de direito.\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\ns) facilitar a fiscalização de todos atos ou serviços por quem de direito;\\n\\nA alternativa D está correta. A referência aqui é o inciso II das regras deontológicas.\\n\\nII - O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim, não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto, consoante as regras contidas no art. 37, caput, e § 4°, da Constituição Federal.\",\"o\":[\"dar publicidade a todos os atos administrativos, tendo em vista que essa é a regra que não pode ser modificada, sendo requisito de eficácia e de moralidade.\",\"divulgar unicamente aos colegas de repartição as normas constantes do Código de Ética.\",\"facilitar a fiscalização de todos os seus atos e serviços por qualquer administrado.\",\"saber distinguir a conduta honesta da desonesta, observando atentamente os princípios que regem a conduta do Administrador Público e a probidade administrativa.\"],\"g\":3},{\"_id\":73,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2019\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com o disposto no Código de Ética Profissional que rege o exercício das atribuições do cargo\\nde servidor público federal, assinale a alternativa correta.\",\"c\":\"A alternativa A está incorreta. Nos termos do inciso IV, os atos praticados pelo servidor em sua vida privada poderão acrescer ou diminuir o seu bom conceito na vida funcional.\\n\\nA alternativa B está incorreta. Nas situações de greve, o servidor deve zelar pelas exigências específicas da defesa da vida e da segurança coletiva (inciso XIV, “j”).\\n\\nA alternativa C está incorreta. Toda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço público (inciso XII).\\n\\nA alternativa D está correta. O Código de Ética não faz nenhuma ressalva ou distinção quanto aos servidores que estejam em período probatório.\",\"o\":[\"Os atos praticados pelo servidor público, no cotidiano de sua vida privada, não poderão acrescer ou diminuir o seu bom conceito na vida funcional, mesmo aqueles não relacionados ao exercício do cargo.\",\"Durante o exercício de greve, o servidor deverá zelar e dedicar-se notadamente pelo bom arquivamento da documentação existente na repartição.\",\"Toda ausência ao trabalho, pelo servidor público, ainda que justificada, é motivo de desmoralização e desumanidade para com os usuários do serviço público.\",\"Ainda que o servidor encontre-se em estágio probatório, deverá representar sua chefia imediata em qualquer ato ilegal praticado no exercício das atribuições do cargo.\"],\"g\":3},{\"_id\":74,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2019\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Considerando-se o Decreto nº. 1.171 de 22 de junho de 1994, que aprova o Código de Ética Profissional\\ndo Servidor Público Civil do Poder Executivo Federal, analise as afirmativas e assinale a que NÃO\\nconcorda com os preceitos doutrinários.\",\"c\":\"Aqui devemos marcar a alternativa incorreta. Nossa resposta é a alternativa A, pois o servidor deve exercer com estrita moderação as prerrogativas funcionais que lhe sejam atribuídas, abstendo-se de fazê-lo contrariamente aos legítimos interesses dos usuários do serviço público e dos jurisdicionados administrativos (inciso XIV, “t”).\",\"o\":[\"O servidor deve exercer as prerrogativas funcionais que lhe sejam atribuídas, ainda que alheias aos interesses dos usuários do serviço público e dos jurisdicionados administrativos.\",\"O servidor deve prestar toda sua atenção às ordens legais de seus superiores, velando atentamente por seu cumprimento e, assim, evitando conduta negligente.\",\"O servidor deve participar dos movimentos e dos estudos que se relacionem com a melhoria do exercício de suas funções, tendo por escopo a realização do bem comum.\",\"O servidor deve cumprir, de acordo com as normas do serviço e com as instruções superiores, as tarefas de seu cargo ou função, tanto quanto possível, com critério, segurança e rapidez, mantendo sempre tudo em boa ordem.\"],\"g\":0},{\"_id\":75,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2019\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Em relação à definição de servidor público dada pelo Código de Ética Profissional do Servidor Público\\nCivil do Poder Executivo Federal, é correto afirmar que\",\"c\":\"Nos termos do inciso XXIV, para fins de apuração do comprometimento ético, entende-se por servidor público todo aquele que, por força de lei, contrato ou de qualquer ato jurídico, preste serviços de natureza permanente, temporária ou excepcional, ainda que sem retribuição financeira, desde que ligado direta ou indiretamente a qualquer órgão do poder estatal, como as autarquias, as fundações públicas, as entidades\\n\\nAula 15 - Legislação\\n\\nparaestatais, as empresas públicas e as sociedades de economia mista, ou em qualquer setor onde prevaleça o interesse do Estado.\\n\\nA definição de servidor público adotado pelo Decreto, portanto, é bastante ampla, alcançando não apenas servidores estatutários e empregados públicos, mas também pessoas que tenham vínculo precário com a Administração Pública: colaboradores contratados, terceirizados, estagiários, entre outros.\",\"o\":[\"se considera servidor público somente aqueles que são detentores de cargo efetivo e estáveis no serviço público.\",\"o contratado no serviço público, em hipótese alguma, pode ser penalizado com uma pena de censura, pois não é servidor estável no serviço público.\",\"para fins de apuração do comprometimento ético, o prestador de serviços temporários e excepcionais, no âmbito da administração, também é considerado servidor público.\",\"para fins de apuração do comprometimento ético, somente o servidor habilitado em concurso público é considerado como servidor público.\"],\"g\":2},{\"_id\":76,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2019\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Conforme o Código de Ética Profissional no Serviço Público, a moralidade da Administração Pública\",\"c\":\"Nos termos do inciso III, a moralidade da Administração Pública não se limita à distinção entre o bem e o mal, devendo ser acrescida da ideia de que o fim é sempre o bem comum. O equilíbrio entre a legalidade e a finalidade, na conduta do servidor público, é que poderá consolidar a moralidade do ato administrativo.\",\"o\":[\"relaciona-se exclusivamente com os conceitos de legalidade e ilegalidade.\",\"consolida-se pelo equilíbrio entre a legalidade e a finalidade.\",\"limita-se à distinção entre o bem e o mal.\",\"não necessariamente redunda na ideia de que o fim é sempre o bem comum.\"],\"g\":1},{\"_id\":77,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2016\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O Decreto nº. 1.171, de 22 de junho de 1994, aprova o Código de Ética Profissional do Servidor Público\\nCivil do Poder Executivo Federal. Sobre as vedações, assinale a alternativa que NÃO caracteriza uma\\nvedação ao servidor público.\",\"c\":\"Aula 15 - Legislação\\n\\nNosso erro está na alternativa D, já que ela não apresenta uma vedação, e sim um dever do servidor. Questão fácil, não é mesmo!?\\n\\nXIV - São deveres fundamentais do servidor público:\\n\\nt) exercer com estrita moderação as prerrogativas funcionais que lhe sejam atribuídas, abstendo-se de fazê-lo contrariamente aos legítimos interesses dos usuários do serviço público e dos jurisdicionados administrativos;\",\"o\":[\"Dar o seu concurso a qualquer instituição que atente contra a moral, a honestidade ou a dignidade da pessoa humana.\",\"Ser, em função de seu espírito de solidariedade, conivente com erro ou infração a este Código de Ética ou ao Código de Ética de sua profissão.\",\"Usar de artifícios para procrastinar ou dificultar o exercício regular de direito por qualquer pessoa, causando-lhe dano moral ou material.\",\"Exercer com estrita moderação as prerrogativas funcionais que lhe sejam atribuídas, abstendo-se de fazê-lo contrariamente aos legítimos interesses dos usuários do serviço público e dos jurisdicionados administrativos.\"],\"g\":3},{\"_id\":78,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2013\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Conforme previsto no Código de Ética do Servidor Público, são deveres fundamentais do servidor\\npúblico, EXCETO:\",\"c\":\"Esta é uma questão meio boba. Ela nos pede para marcarmos a alternativa que corresponde a um dever, mas indica como resposta a alternativa C, que na realidade traz uma proibição com “sinal trocado”. A rigor não podemos recorrer e nem questionar o gabarito, mas não é uma questão muito bem elaborada.\\n\\nXV - É vedado ao servidor público:\\n\\nb) prejudicar deliberadamente a reputação de outros servidores ou de cidadãos que deles\\n\\ndependam;\",\"o\":[\"Ser cortês, ter urbanidade, disponibilidade e atenção, respeitando a capacidade e as limitações individuais de todos os usuários do serviço público, sem qualquer espécie de preconceito ou distinção de raça, sexo, nacionalidade, cor, idade, religião, cunho político e posição social, abstendo-se, dessa forma, de causar-lhes dano moral.\",\"Zelar, no exercício do direito de greve, pelas exigências específicas da defesa da vida e da segurança coletiva.\",\"Não prejudicar deliberadamente a reputação de outros servidores ou de cidadãos que deles dependam.\",\"Facilitar a fiscalização de todos os atos ou serviços por quem de direito.\"],\"g\":2},{\"_id\":79,\"t\":\"Código de Ética do Servidor (Decreto 1.171/1994) e Comissões de Ética\",\"b\":\"Cebraspe\",\"src\":\"MG UFU · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Na hipótese de um servidor público civil federal vislumbrar a prática de uma conduta, por parte de seu\\nsuperior hierárquico, que possa comprometer o interesse público, ele deverá\",\"c\":\"Entre os deveres fundamentais que aparecem no inciso XIV detemos o de ter respeito à hierarquia, porém sem nenhum temor de representar contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal (alínea “h”).\",\"o\":[\"guardar para si o que vislumbrou, considerando que não possui competência legal para denunciar ou representar seu superior hierárquico.\",\"abster-se de tomar qualquer espécie de providência em respeito ao chamado “princípio da hierarquia”. Aula 15 - Legislação\",\"ter respeito à hierarquia, sem, contudo, ter nenhum temor de representar contra qualquer comprometimento indevido da estrutura em que se funda o Poder Estatal.\",\"denunciar de forma anônima seu superior hierárquico.\"],\"g\":2}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]}};window.EMBEDDED_CONTENT=window.EMBEDDED_CONTENT||{};for(var k in d){var ex=window.EMBEDDED_CONTENT[k]||{};var pv=ex.questoesPdf;var pa=Array.isArray(pv)?pv:(pv?[pv]:[]);var m=Object.assign({},ex,d[k]);var comb=(d[k].questoesPdf||[]).concat(pa);var seen={},uniq=[];for(var qi=0;qi<comb.length;qi++){var s=comb[qi];var kk=(s&&s.title||"")+"|"+((s&&s.content||"").length);if(!seen[kk]){seen[kk]=1;uniq.push(s);}}m.questoesPdf=uniq;window.EMBEDDED_CONTENT[k]=m;}})();
